window.__U50PRO_CONSOLE_DOC__ = "\u003c!DOCTYPE html>\n\u003chtml lang=\"zh-CN\">\n\u003chead>\n\u003cmeta charset=\"utf-8\">\n\u003cmeta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\">\n\u003ctitle>U50 Pro 控制台\u003c/title>\n\u003clink rel=\"icon\" href=\"data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 32 32'%3E%3Crect width='32' height='32' rx='7' fill='%232563eb'/%3E%3Crect x='7' y='18' width='4' height='8' rx='1' fill='%23fff'/%3E%3Crect x='14' y='13' width='4' height='13' rx='1' fill='%23fff'/%3E%3Crect x='21' y='8' width='4' height='18' rx='1' fill='%23fff'/%3E%3C/svg%3E\">\n\u003clink rel=\"stylesheet\" href=\"https://HOST/u50pro-portable/style.css\">\n\u003c/head>\n\u003cbody>\n\n\u003c!-- 登录（v1.7.0 随身版：蓝色头图 + 无确认按钮，输对密码自动进；直连模式，不用电脑） -->\n\u003cdiv id=\"login-view\" class=\"login-wrap\">\n  \u003cdiv class=\"login-card\">\n    \u003cdiv class=\"login-hero\">\n      \u003cdiv class=\"login-mark\" aria-hidden=\"true\">\u003ci>\u003c/i>\u003ci>\u003c/i>\u003ci>\u003c/i>\u003ci>\u003c/i>\u003c/div>\n      \u003cdiv class=\"login-eyebrow\">ZTE · MU5120\u003c/div>\n      \u003ch1>U50 Pro 控制台 \u003cspan class=\"ver-pill light\">v1.7.0 随身版\u003c/span>\u003c/h1>\n      \u003cp class=\"login-sub\">中兴 U50 Pro 随身 WiFi 第三方管理后台\u003c/p>\n    \u003c/div>\n    \u003cdiv class=\"login-body\">\n      \u003cdiv class=\"field\">\n        \u003clabel for=\"login-addr\">路由器地址\u003c/label>\n        \u003cinput id=\"login-addr\" class=\"input\" type=\"text\" value=\"http://192.168.0.1\" autocomplete=\"off\" spellcheck=\"false\">\n        \u003cdiv class=\"hint\">随身版：地址固定为当前原厂页面，不用改。\u003c/div>\n      \u003c/div>\n      \u003cdiv class=\"field\">\n        \u003clabel for=\"login-pass\">登录密码\u003c/label>\n        \u003cinput id=\"login-pass\" class=\"input\" type=\"password\" autocomplete=\"current-password\" placeholder=\"输入路由器后台密码，输对自动登录\">\n        \u003cdiv class=\"hint\">不用点按钮：输完密码停一下就自动登录，密码错了下面会显示“密码错误”。\u003c/div>\n      \u003c/div>\n      \u003cdiv id=\"login-status\" class=\"login-status\">\u003cspan class=\"spin\">\u003c/span>正在登录…\u003c/div>\n      \u003cdiv id=\"login-err\" class=\"err\" role=\"alert\">\u003c/div>\n      \u003cp class=\"login-foot\">随身版：不用电脑，手机连着 U50 的 Wi-Fi 就能用。密码只在浏览器内存里做登录计算，不保存，关掉页面就要重新输。登录后每 2 秒自动刷新一次状态。VPN / 代理功能本设备接口不提供，不在控制台里。\u003c/p>\n      \u003cp class=\"login-ver\">控制台版本 \u003cb>v1.7.0 随身版\u003c/b> · 直连模式 · 不用电脑 · 双频合一已加入 Wi-Fi 页\u003c/p>\n    \u003c/div>\n  \u003c/div>\n\u003c/div>\n\n\u003c!-- 主界面 -->\n\u003cdiv id=\"app-view\" hidden>\n  \u003cheader class=\"topbar\">\n    \u003cdiv class=\"logo\">U50 Pro 控制台\u003csmall>MU5120\u003c/small>\u003cspan class=\"ver-pill\">v1.7.0 随身版\u003c/span>\u003c/div>\n    \u003cdiv class=\"spacer\">\u003c/div>\n    \u003cdiv class=\"conn\">\u003cspan id=\"conn-dot\" class=\"dot\">\u003c/span>\u003cspan id=\"conn-text\">未连接\u003c/span>\u003c/div>\n    \u003cbutton id=\"refresh-btn\" class=\"btn ghost small\" type=\"button\">刷新\u003c/button>\n    \u003cbutton id=\"logout-btn\" class=\"btn ghost small\" type=\"button\">退出登录\u003c/button>\n  \u003c/header>\n\n  \u003cnav class=\"tabs\" id=\"tabs\" role=\"tablist\">\n    \u003cbutton class=\"tab active\" data-page=\"overview\" type=\"button\">总览\u003c/button>\n    \u003cbutton class=\"tab\" data-page=\"network\" type=\"button\">网络\u003c/button>\n    \u003cbutton class=\"tab\" data-page=\"wifi\" type=\"button\">Wi-Fi\u003c/button>\n    \u003cbutton class=\"tab\" data-page=\"traffic\" type=\"button\">流量\u003c/button>\n    \u003cbutton class=\"tab\" data-page=\"sms\" type=\"button\">短信 \u003cspan id=\"sms-badge\" class=\"pill red\" hidden>0\u003c/span>\u003c/button>\n    \u003cbutton class=\"tab\" data-page=\"devices\" type=\"button\">连接设备\u003c/button>\n    \u003cbutton class=\"tab\" data-page=\"security\" type=\"button\">安全\u003c/button>\n    \u003cbutton class=\"tab\" data-page=\"advanced\" type=\"button\">高级\u003c/button>\n    \u003cbutton class=\"tab\" data-page=\"settings\" type=\"button\">设置\u003c/button>\n  \u003c/nav>\n\n  \u003cmain class=\"wrap\">\n\n    \u003c!-- 总览 -->\n    \u003csection class=\"page active\" id=\"page-overview\">\n      \u003cdiv class=\"page-head\">\u003ch1>总览\u003c/h1>\u003cp>设备状态、信号与电池，一眼看完。\u003c/p>\u003c/div>\n      \u003cdiv class=\"card quick\">\n        \u003cdiv class=\"row quick-row\">\n          \u003cbutton id=\"qa-sms\" class=\"btn small\" type=\"button\">发短信\u003c/button>\n          \u003cbutton id=\"qa-sms-inbox\" class=\"btn ghost small\" type=\"button\">短信收件箱 \u003cspan id=\"qa-sms-badge\" class=\"pill red\" hidden>0\u003c/span>\u003c/button>\n          \u003cbutton id=\"qa-refresh\" class=\"btn ghost small\" type=\"button\">刷新状态\u003c/button>\n          \u003cbutton id=\"qa-settings\" class=\"btn ghost small\" type=\"button\">重启 / 设备设置\u003c/button>\n        \u003c/div>\n        \u003cdiv class=\"sub mt8\">常用操作一步直达：发短信、看收件箱（含未读数）、刷新状态、去设置页重启或关机。\u003c/div>\n      \u003c/div>\n\n      \u003cdiv class=\"card\">\n        \u003cdiv class=\"grid\" style=\"margin-top:0\">\n          \u003cdiv class=\"stat\">\u003cdiv class=\"k\">接入设备\u003c/div>\u003cdiv class=\"v\" id=\"ov-sum-dev\">—\u003c/div>\u003cdiv class=\"s\" id=\"ov-sum-dev-sub\">—\u003c/div>\u003c/div>\n          \u003cdiv class=\"stat\">\u003cdiv class=\"k\">当前网络\u003c/div>\u003cdiv class=\"v small\" id=\"ov-sum-net\">—\u003c/div>\u003cdiv class=\"s\" id=\"ov-sum-sig\">—\u003c/div>\u003c/div>\n          \u003cdiv class=\"stat\">\u003cdiv class=\"k\">实时速率\u003c/div>\u003cdiv class=\"v small\" id=\"ov-sum-rate\">—\u003c/div>\u003cdiv class=\"s\" id=\"ov-sum-time\">—\u003c/div>\u003c/div>\n        \u003c/div>\n      \u003c/div>\n\n      \u003cdiv class=\"card\">\n        \u003cdiv class=\"row\">\n          \u003cdiv>\n            \u003ch2>当前网络\u003c/h2>\n            \u003cdiv class=\"sub\" id=\"ov-operator\">—\u003c/div>\n          \u003c/div>\n          \u003cdiv class=\"spacer\">\u003c/div>\n          \u003cspan id=\"ov-net-pill\" class=\"pill gray\">—\u003c/span>\n        \u003c/div>\n        \u003cdiv class=\"sig mt14\">\n          \u003cdiv class=\"bars\" id=\"ov-bars\" aria-hidden=\"true\">\u003ci>\u003c/i>\u003ci>\u003c/i>\u003ci>\u003c/i>\u003ci>\u003c/i>\u003ci>\u003c/i>\u003c/div>\n          \u003cdiv class=\"big-net\">\u003cspan id=\"ov-net\">—\u003c/span> \u003csmall id=\"ov-band\">—\u003c/small>\u003c/div>\n          \u003cspan id=\"ov-roam\" class=\"pill gray\" hidden>漫游\u003c/span>\n        \u003c/div>\n        \u003cdiv class=\"grid\">\n          \u003cdiv class=\"stat\">\u003cdiv class=\"k\">下载速率\u003c/div>\u003cdiv class=\"v\" id=\"ov-dl\">—\u003c/div>\u003c/div>\n          \u003cdiv class=\"stat\">\u003cdiv class=\"k\">上传速率\u003c/div>\u003cdiv class=\"v\" id=\"ov-ul\">—\u003c/div>\u003c/div>\n          \u003cdiv class=\"stat\">\u003cdiv class=\"k\">RSRP\u003c/div>\u003cdiv class=\"v\" id=\"ov-rsrp\">—\u003c/div>\u003c/div>\n          \u003cdiv class=\"stat\">\u003cdiv class=\"k\">SINR\u003c/div>\u003cdiv class=\"v\" id=\"ov-sinr\">—\u003c/div>\u003c/div>\n          \u003cdiv class=\"stat\">\u003cdiv class=\"k\">RSRQ\u003c/div>\u003cdiv class=\"v\" id=\"ov-rsrq\">—\u003c/div>\u003c/div>\n          \u003cdiv class=\"stat\">\u003cdiv class=\"k\">信号格数\u003c/div>\u003cdiv class=\"v\" id=\"ov-bars-n\">—\u003c/div>\u003c/div>\n        \u003c/div>\n      \u003c/div>\n\n      \u003cdiv class=\"card\">\n        \u003ch2>设备信息\u003c/h2>\n        \u003cdiv class=\"grid\">\n          \u003cdiv class=\"stat\">\u003cdiv class=\"k\">WAN IPv4\u003c/div>\u003cdiv class=\"v\" id=\"ov-wan4\" style=\"font-size:15px\">—\u003c/div>\u003c/div>\n          \u003cdiv class=\"stat\">\u003cdiv class=\"k\">WAN IPv6\u003c/div>\u003cdiv class=\"v\" id=\"ov-wan6\" style=\"font-size:15px\">—\u003c/div>\u003c/div>\n          \u003cdiv class=\"stat\">\u003cdiv class=\"k\">LAN 地址\u003c/div>\u003cdiv class=\"v\" id=\"ov-lan\" style=\"font-size:15px\">—\u003c/div>\u003c/div>\n          \u003cdiv class=\"stat\">\u003cdiv class=\"k\">IMEI\u003c/div>\u003cdiv class=\"v\" id=\"ov-imei\" style=\"font-size:15px\">—\u003c/div>\u003c/div>\n          \u003cdiv class=\"stat\">\u003cdiv class=\"k\">SIM ICCID\u003c/div>\u003cdiv class=\"v\" id=\"ov-iccid\" style=\"font-size:15px\">—\u003c/div>\u003c/div>\n          \u003cdiv class=\"stat\">\u003cdiv class=\"k\">手机号\u003c/div>\u003cdiv class=\"v\" id=\"ov-phone\" style=\"font-size:15px\">—\u003c/div>\u003c/div>\n          \u003cdiv class=\"stat\">\u003cdiv class=\"k\">固件版本\u003c/div>\u003cdiv class=\"v\" id=\"ov-fw\" style=\"font-size:15px\">—\u003c/div>\u003c/div>\n          \u003cdiv class=\"stat\">\u003cdiv class=\"k\">硬件版本\u003c/div>\u003cdiv class=\"v\" id=\"ov-hw\" style=\"font-size:15px\">—\u003c/div>\u003c/div>\n          \u003cdiv class=\"stat\">\u003cdiv class=\"k\">CPU 使用率\u003c/div>\u003cdiv class=\"v\" id=\"ov-cpu\">—\u003c/div>\u003c/div>\n          \u003cdiv class=\"stat\">\u003cdiv class=\"k\">内存使用率\u003c/div>\u003cdiv class=\"v\" id=\"ov-mem\">—\u003c/div>\u003c/div>\n        \u003c/div>\n        \u003cdiv class=\"sub mt14\" id=\"ov-temps\">温度：—\u003c/div>\n        \u003cdiv class=\"sub mt8\" id=\"ov-cell\">服务小区：—\u003c/div>\n        \u003cdiv class=\"sub mt8\" id=\"ov-ca\">载波聚合：—\u003c/div>\n      \u003c/div>\n\n      \u003cdiv class=\"card\">\n        \u003ch2>联网状态\u003c/h2>\n        \u003cdiv class=\"grid\">\n          \u003cdiv class=\"stat\">\u003cdiv class=\"k\">联网状态\u003c/div>\u003cdiv class=\"v\" id=\"ov-ppp\">—\u003c/div>\u003c/div>\n          \u003cdiv class=\"stat\">\u003cdiv class=\"k\">WAN 模式\u003c/div>\u003cdiv class=\"v\" id=\"ov-wanmode\">—\u003c/div>\u003c/div>\n          \u003cdiv class=\"stat\">\u003cdiv class=\"k\">运行模式\u003c/div>\u003cdiv class=\"v\" id=\"ov-opmode\">—\u003c/div>\u003c/div>\n          \u003cdiv class=\"stat\">\u003cdiv class=\"k\">Wi-Fi\u003c/div>\u003cdiv class=\"v\" id=\"ov-wifi\">—\u003c/div>\u003c/div>\n          \u003cdiv class=\"stat\">\u003cdiv class=\"k\">2.4G 连接数\u003c/div>\u003cdiv class=\"v\" id=\"ov-sta24\">—\u003c/div>\u003c/div>\n          \u003cdiv class=\"stat\">\u003cdiv class=\"k\">5G 连接数\u003c/div>\u003cdiv class=\"v\" id=\"ov-sta5\">—\u003c/div>\u003c/div>\n        \u003c/div>\n        \u003cdiv class=\"sub mt14\">上次刷新：\u003cspan id=\"ov-updated\">—\u003c/span> · 每 2 秒自动刷新\u003c/div>\n      \u003c/div>\n\n            \u003cdiv class=\"card\">\n              \u003ch2>电池\u003c/h2>\n              \u003cdiv class=\"batt mt8\">\n                \u003cdiv class=\"pct\">\u003cspan id=\"bt-pct\">—\u003c/span>\u003csmall>%\u003c/small>\u003c/div>\n                \u003cdiv>\n                  \u003cdiv>\u003cspan id=\"bt-state\" class=\"pill gray\">—\u003c/span>\u003c/div>\n                  \u003cdiv class=\"sub mt8\" id=\"bt-detail\">—\u003c/div>\n                \u003c/div>\n              \u003c/div>\n              \u003cdiv class=\"grid\">\n                \u003cdiv class=\"stat\">\u003cdiv class=\"k\">电池温度\u003c/div>\u003cdiv class=\"v\" id=\"bt-temp\">—\u003c/div>\u003c/div>\n                \u003cdiv class=\"stat\">\u003cdiv class=\"k\">变化速率\u003c/div>\u003cdiv class=\"v\" id=\"bt-rate\">—\u003c/div>\u003c/div>\n                \u003cdiv class=\"stat\">\u003cdiv class=\"k\">预计充满 / 用完\u003c/div>\u003cdiv class=\"v small\" id=\"bt-remain\">—\u003c/div>\u003c/div>\n                \u003cdiv class=\"stat\">\u003cdiv class=\"k\">电压\u003c/div>\u003cdiv class=\"v\" id=\"bt-volt\">—\u003c/div>\u003c/div>\n                \u003cdiv class=\"stat\">\u003cdiv class=\"k\">电流\u003c/div>\u003cdiv class=\"v\" id=\"bt-curr\">—\u003c/div>\u003c/div>\n                \u003cdiv class=\"stat\">\u003cdiv class=\"k\">健康度\u003c/div>\u003cdiv class=\"v\" id=\"bt-health\">—\u003c/div>\u003c/div>\n              \u003c/div>\n            \u003c/div>\n            \u003cdiv class=\"card\">\n              \u003ch2>最近 12 小时电量\u003c/h2>\n              \u003cdiv class=\"sub\">存在浏览器本地（localStorage），只记你打开控制台期间的采样；路由器不返回的历史不会虚构。\u003c/div>\n              \u003csvg id=\"bt-chart\" class=\"chart\" viewBox=\"0 0 600 120\" preserveAspectRatio=\"none\" role=\"img\" aria-label=\"电量趋势图\">\u003c/svg>\n              \u003cdiv class=\"chart-note\" id=\"bt-chart-note\">暂无采样数据。\u003c/div>\n            \u003c/div>\n            \u003cdiv class=\"card\">\n              \u003ch2>温度\u003c/h2>\n              \u003cdiv class=\"grid\" id=\"bt-temps\">\u003c/div>\n              \u003cdiv class=\"sub mt8\">只显示路由器实际返回的温度字段；没有返回的不会虚构。\u003c/div>\n            \u003c/div>\n    \u003c/section>\n\n    \u003c!-- 网络：模式 / 数据 / APN / 锁频段 / 锁小区 / SIM 与更新状态 -->\n    \u003csection class=\"page\" id=\"page-network\">\n      \u003cdiv class=\"page-head\">\u003ch1>网络\u003c/h1>\u003cp>移动网络、APN、频段锁定与 SIM 卡。\u003c/p>\u003c/div>\n      \u003cdiv class=\"card\">\n        \u003ch2>网络模式\u003c/h2>\n        \u003cdiv class=\"sub\">当前：\u003cb id=\"net-mode-cur\">—\u003c/b>\u003c/div>\n        \u003cdiv class=\"field mt14\">\u003clabel for=\"net-mode\">切换网络模式\u003c/label>\n          \u003cselect id=\"net-mode\" class=\"input\">\n            \u003coption value=\"WL_AND_5G\">5G / 4G / 3G（自动）\u003c/option>\n            \u003coption value=\"LTE_AND_5G\">5G NSA\u003c/option>\n            \u003coption value=\"Only_5G\">5G SA（仅 5G 独立组网）\u003c/option>\n            \u003coption value=\"Only_LTE\">仅 4G\u003c/option>\n          \u003c/select>\n          \u003cdiv class=\"hint\">切换后可能短暂断网，设备会重新注册网络。\u003c/div>\n        \u003c/div>\n        \u003cbutton id=\"net-mode-save\" class=\"btn\" type=\"button\">保存网络模式\u003c/button>\n      \u003c/div>\n\n      \u003cdiv class=\"card\">\n        \u003ch2>蜂窝数据与漫游\u003c/h2>\n        \u003cdiv class=\"grid\">\n          \u003cdiv class=\"stat\">\u003cdiv class=\"k\">蜂窝数据\u003c/div>\u003cdiv class=\"v small\" id=\"net-data-state\">—\u003c/div>\u003c/div>\n          \u003cdiv class=\"stat\">\u003cdiv class=\"k\">数据漫游\u003c/div>\u003cdiv class=\"v small\" id=\"net-roam-state\">—\u003c/div>\u003c/div>\n        \u003c/div>\n        \u003cdiv class=\"row mt14\">\n          \u003cbutton id=\"net-data-toggle\" class=\"btn\" type=\"button\">断开蜂窝数据\u003c/button>\n          \u003cbutton id=\"net-roam-toggle\" class=\"btn ghost\" type=\"button\">开启数据漫游\u003c/button>\n        \u003c/div>\n        \u003cdiv class=\"sub mt8\">断开后设备不上网，Wi-Fi 内的设备也断网；再点一次恢复连接。漫游开关只在出境 / 用异地卡时才需要开。\u003c/div>\n      \u003c/div>\n\n      \u003cdiv class=\"card\">\n        \u003cdiv class=\"row\">\n          \u003cdiv>\u003ch2>APN 管理\u003c/h2>\u003cdiv class=\"sub\" id=\"apn-summary\">—\u003c/div>\u003c/div>\n          \u003cdiv class=\"spacer\">\u003c/div>\n          \u003cbutton id=\"apn-refresh\" class=\"btn ghost small\" type=\"button\">刷新\u003c/button>\n        \u003c/div>\n        \u003cdiv class=\"field mt14\">\u003clabel for=\"apn-mode\">APN 模式\u003c/label>\n          \u003cselect id=\"apn-mode\" class=\"input\">\n            \u003coption value=\"auto\">自动（按 SIM 卡自动匹配）\u003c/option>\n            \u003coption value=\"manual\">手动（用下面选中的配置）\u003c/option>\n          \u003c/select>\n        \u003c/div>\n        \u003cdiv class=\"field\">\u003clabel for=\"apn-profile\">手动配置\u003c/label>\n          \u003cselect id=\"apn-profile\" class=\"input\">\u003c/select>\n          \u003cdiv class=\"hint\">列表来自路由器里保存的 APN 配置（最多 20 个）。\u003c/div>\n        \u003c/div>\n        \u003cdiv class=\"row\">\n          \u003cbutton id=\"apn-apply\" class=\"btn\" type=\"button\">应用\u003c/button>\n          \u003cbutton id=\"apn-add\" class=\"btn ghost\" type=\"button\">新增配置\u003c/button>\n          \u003cbutton id=\"apn-edit\" class=\"btn ghost\" type=\"button\">编辑选中\u003c/button>\n          \u003cbutton id=\"apn-del\" class=\"btn ghost\" type=\"button\">删除选中\u003c/button>\n        \u003c/div>\n        \u003cdiv id=\"apn-form\" class=\"mt14\" hidden>\n          \u003cdiv class=\"field\">\u003clabel for=\"apn-f-name\">配置名称（必填）\u003c/label>\n            \u003cinput id=\"apn-f-name\" class=\"input\" type=\"text\" autocomplete=\"off\" placeholder=\"例如 中国移动\">\n          \u003c/div>\n          \u003cdiv class=\"field\">\u003clabel for=\"apn-f-apn\">APN（必填）\u003c/label>\n            \u003cinput id=\"apn-f-apn\" class=\"input\" type=\"text\" autocomplete=\"off\" placeholder=\"例如 cmnet\">\n            \u003cdiv class=\"hint\">不知道填什么就问运营商；填错会上不了网。\u003c/div>\n          \u003c/div>\n          \u003cdiv class=\"field\">\u003clabel for=\"apn-f-auth\">鉴权方式\u003c/label>\n            \u003cselect id=\"apn-f-auth\" class=\"input\">\n              \u003coption value=\"none\">无鉴权\u003c/option>\n              \u003coption value=\"pap\">PAP\u003c/option>\n              \u003coption value=\"chap\">CHAP\u003c/option>\n            \u003c/select>\n          \u003c/div>\n          \u003cdiv class=\"field\">\u003clabel for=\"apn-f-user\">用户名\u003c/label>\n            \u003cinput id=\"apn-f-user\" class=\"input\" type=\"text\" autocomplete=\"off\">\n          \u003c/div>\n          \u003cdiv class=\"field\">\u003clabel for=\"apn-f-pass\">密码\u003c/label>\n            \u003cinput id=\"apn-f-pass\" class=\"input\" type=\"password\" autocomplete=\"off\">\n          \u003c/div>\n          \u003cdiv class=\"field\">\u003clabel for=\"apn-f-pdp\">PDP 类型\u003c/label>\n            \u003cselect id=\"apn-f-pdp\" class=\"input\">\n              \u003coption value=\"IPv4v6\">IPv4v6\u003c/option>\n              \u003coption value=\"IP\">IPv4\u003c/option>\n              \u003coption value=\"IPv6\">IPv6\u003c/option>\n            \u003c/select>\n          \u003c/div>\n          \u003cdiv class=\"row\">\n            \u003cbutton id=\"apn-form-save\" class=\"btn\" type=\"button\">保存配置\u003c/button>\n            \u003cbutton id=\"apn-form-cancel\" class=\"btn ghost\" type=\"button\">取消\u003c/button>\n          \u003c/div>\n        \u003c/div>\n        \u003cdiv class=\"sub mt14\" id=\"apn-note\">当前 APN：—\u003c/div>\n      \u003c/div>\n\n      \u003cdiv class=\"card\">\n        \u003ch2>频段锁定\u003c/h2>\n        \u003cdiv class=\"sub\">当前锁定：\u003cb id=\"band-cur\">—\u003c/b>\u003c/div>\n        \u003cdiv class=\"sub mt8\">锁频段需要开发者会话，第一次点保存时会自动建立（用你登录的密码），不用你多操作。锁错频段可能导致没信号，解除限制即可恢复。\u003c/div>\n        \u003ch3 class=\"mt14\">LTE（4G）频段\u003c/h3>\n        \u003cdiv class=\"chips\" id=\"band-lte\">\u003c/div>\n        \u003cdiv class=\"row mt8\">\n          \u003cbutton id=\"band-lte-save\" class=\"btn small\" type=\"button\">保存 LTE 频段\u003c/button>\n          \u003cbutton id=\"band-lte-clear\" class=\"btn ghost small\" type=\"button\">解除 LTE 限制\u003c/button>\n        \u003c/div>\n        \u003ch3 class=\"mt14\">5G NSA 频段\u003c/h3>\n        \u003cdiv class=\"chips\" id=\"band-nsa\">\u003c/div>\n        \u003cdiv class=\"row mt8\">\n          \u003cbutton id=\"band-nsa-save\" class=\"btn small\" type=\"button\">保存 5G NSA 频段\u003c/button>\n          \u003cbutton id=\"band-nsa-clear\" class=\"btn ghost small\" type=\"button\">解除 NSA 限制\u003c/button>\n        \u003c/div>\n        \u003ch3 class=\"mt14\">5G SA 频段\u003c/h3>\n        \u003cdiv class=\"chips\" id=\"band-sa\">\u003c/div>\n        \u003cdiv class=\"row mt8\">\n          \u003cbutton id=\"band-sa-save\" class=\"btn small\" type=\"button\">保存 5G SA 频段\u003c/button>\n          \u003cbutton id=\"band-sa-clear\" class=\"btn ghost small\" type=\"button\">解除 SA 限制\u003c/button>\n        \u003c/div>\n        \u003cdiv class=\"field mt14\">\u003clabel for=\"band-nr-extra\">5G 补充频段（不在上面列表里的，逗号分隔，1–261）\u003c/label>\n          \u003cinput id=\"band-nr-extra\" class=\"input small\" type=\"text\" autocomplete=\"off\" placeholder=\"例如 229\">\n          \u003cdiv class=\"hint\">填了会一起加进 NSA 和 SA 的保存里；留空不管。\u003c/div>\n        \u003c/div>\n      \u003c/div>\n\n      \u003cdiv class=\"card\">\n        \u003cdiv class=\"row\">\n          \u003cdiv>\u003ch2>小区锁定\u003c/h2>\u003cdiv class=\"sub\">当前锁定：\u003cb id=\"cell-cur\">—\u003c/b>\u003c/div>\u003c/div>\n          \u003cdiv class=\"spacer\">\u003c/div>\n          \u003cbutton id=\"cell-scan\" class=\"btn ghost small\" type=\"button\">重新扫描邻区\u003c/button>\n        \u003c/div>\n        \u003cdiv class=\"sub mt8\">点一行候选小区会填进下面的锁定表单（默认最强那个）。锁小区只改小区锁定，不改频段；换地方用之前记得解除。\u003c/div>\n        \u003cdiv class=\"field mt14\">\u003cinput id=\"cell-filter\" class=\"input small\" type=\"search\" placeholder=\"搜索 PCI、ARFCN、频段…\" autocomplete=\"off\">\u003c/div>\n        \u003cdiv id=\"cell-list\" class=\"list\">\u003c/div>\n        \u003cdiv id=\"cell-empty\" class=\"empty\" hidden>暂无候选小区，请点“重新扫描邻区”。\u003c/div>\n        \u003cdiv class=\"mt14\">\n          \u003cdiv class=\"field\">\u003clabel for=\"cell-rat\">制式\u003c/label>\n            \u003cselect id=\"cell-rat\" class=\"input\">\n              \u003coption value=\"NR\">5G（NR）\u003c/option>\n              \u003coption value=\"LTE\">4G（LTE）\u003c/option>\n            \u003c/select>\n          \u003c/div>\n          \u003cdiv class=\"field\">\u003clabel for=\"cell-pci\">PCI\u003c/label>\n            \u003cinput id=\"cell-pci\" class=\"input\" type=\"number\" min=\"0\" inputmode=\"numeric\" placeholder=\"5G：0–1007；4G：0–503\">\n          \u003c/div>\n          \u003cdiv class=\"field\">\u003clabel for=\"cell-arfcn\">ARFCN\u003c/label>\n            \u003cinput id=\"cell-arfcn\" class=\"input\" type=\"number\" min=\"0\" inputmode=\"numeric\" placeholder=\"5G：0–800000；4G：0–68935\">\n          \u003c/div>\n          \u003cdiv class=\"field\">\u003clabel for=\"cell-band\">频段\u003c/label>\n            \u003cinput id=\"cell-band\" class=\"input\" type=\"number\" min=\"1\" max=\"261\" inputmode=\"numeric\" placeholder=\"例如 41\">\n          \u003c/div>\n          \u003cdiv class=\"field\" id=\"cell-scs-wrap\">\u003clabel for=\"cell-scs\">SCS（子载波间隔，仅 5G）\u003c/label>\n            \u003cinput id=\"cell-scs\" class=\"input\" type=\"number\" min=\"15\" max=\"120\" inputmode=\"numeric\" placeholder=\"41/77/78/79 频段一般是 30，其他 15\">\n          \u003c/div>\n          \u003cdiv class=\"row\">\n            \u003cbutton id=\"cell-lock\" class=\"btn\" type=\"button\">锁定所选小区\u003c/button>\n            \u003cbutton id=\"cell-unlock\" class=\"btn ghost\" type=\"button\">解除小区锁定\u003c/button>\n          \u003c/div>\n        \u003c/div>\n      \u003c/div>\n\n      \u003cdiv class=\"card\">\n        \u003ch2>SIM 卡状态\u003c/h2>\n        \u003cdiv class=\"grid\">\n          \u003cdiv class=\"stat\">\u003cdiv class=\"k\">PIN 状态\u003c/div>\u003cdiv class=\"v small\" id=\"sim-pin\">—\u003c/div>\u003c/div>\n          \u003cdiv class=\"stat\">\u003cdiv class=\"k\">PIN 剩余次数\u003c/div>\u003cdiv class=\"v\" id=\"sim-pin-left\">—\u003c/div>\u003c/div>\n          \u003cdiv class=\"stat\">\u003cdiv class=\"k\">PUK 剩余次数\u003c/div>\u003cdiv class=\"v\" id=\"sim-puk-left\">—\u003c/div>\u003c/div>\n          \u003cdiv class=\"stat\">\u003cdiv class=\"k\">Modem 状态\u003c/div>\u003cdiv class=\"v small\" id=\"sim-modem\">—\u003c/div>\u003c/div>\n        \u003c/div>\n        \u003cdiv class=\"warn mt14\">输错 PIN 有锁卡风险：原厂固件对 PIN 尝试次数的判定有问题，输错可能直接锁卡（只剩 PUK 解锁，PUK 输错 10 次卡就作废）。上面显示的是设备返回的真实剩余次数，次数不多时不要试密码；不确定就先去官方后台或营业厅确认。\u003c/div>\n        \u003cdiv class=\"field mt14\">\u003clabel for=\"pin-enter\">输入 PIN（开机后提示输入 PIN 时用）\u003c/label>\n          \u003cinput id=\"pin-enter\" class=\"input\" type=\"password\" inputmode=\"numeric\" autocomplete=\"off\" maxlength=\"8\" placeholder=\"4–8 位 PIN\">\n        \u003c/div>\n        \u003cdiv class=\"row\">\u003cbutton id=\"pin-enter-btn\" class=\"btn\" type=\"button\">提交 PIN\u003c/button>\u003c/div>\n        \u003cdiv class=\"field mt14\">\u003clabel for=\"pin-old\">改 PIN：当前 PIN\u003c/label>\n          \u003cinput id=\"pin-old\" class=\"input\" type=\"password\" inputmode=\"numeric\" autocomplete=\"off\" maxlength=\"8\">\n        \u003c/div>\n        \u003cdiv class=\"field\">\u003clabel for=\"pin-new\">改 PIN：新 PIN\u003c/label>\n          \u003cinput id=\"pin-new\" class=\"input\" type=\"password\" inputmode=\"numeric\" autocomplete=\"off\" maxlength=\"8\" placeholder=\"4–8 位\">\n        \u003c/div>\n        \u003cdiv class=\"row\">\u003cbutton id=\"pin-change-btn\" class=\"btn\" type=\"button\">修改 PIN\u003c/button>\u003c/div>\n        \u003cdiv class=\"field mt14\">\u003clabel for=\"pin-disable-old\">关闭 PIN：当前 PIN\u003c/label>\n          \u003cinput id=\"pin-disable-old\" class=\"input\" type=\"password\" inputmode=\"numeric\" autocomplete=\"off\" maxlength=\"8\">\n        \u003c/div>\n        \u003cdiv class=\"row\">\u003cbutton id=\"pin-disable-btn\" class=\"btn ghost\" type=\"button\">关闭 PIN 校验\u003c/button>\u003c/div>\n        \u003cdiv class=\"field mt14\">\u003clabel for=\"puk-code\">PUK 解锁：PUK 码（SIM 卡托 / 卡套上印的 8 位码）\u003c/label>\n          \u003cinput id=\"puk-code\" class=\"input\" type=\"password\" inputmode=\"numeric\" autocomplete=\"off\" maxlength=\"8\" placeholder=\"8 位 PUK\">\n        \u003c/div>\n        \u003cdiv class=\"field\">\u003clabel for=\"puk-new-pin\">PUK 解锁后设的新 PIN\u003c/label>\n          \u003cinput id=\"puk-new-pin\" class=\"input\" type=\"password\" inputmode=\"numeric\" autocomplete=\"off\" maxlength=\"8\" placeholder=\"4–8 位\">\n        \u003c/div>\n        \u003cdiv class=\"row\">\u003cbutton id=\"puk-btn\" class=\"btn danger\" type=\"button\">PUK 解锁\u003c/button>\u003c/div>\n        \u003cdiv class=\"sub mt8\">PIN / PUK 只在输入框里出现一次，不保存、不回显。接口依据：实机 service.js（ENTER_PIN / ENTER_PUK / ENABLE_PIN / DISABLE_PIN）。\u003c/div>\n      \u003c/div>\n\n      \u003cdiv class=\"card\">\n        \u003ch2>USSD（查话费、查流量、办业务）\u003c/h2>\n        \u003cdiv class=\"sub\">运营商的 USSD 代码，例如移动查话费 \u003ccode>*#888#\u003c/code>、联通 \u003ccode>*#101#\u003c/code>、电信 \u003ccode>*#108#\u003c/code>（各运营商代码不同，问运营商）。发出去后等几秒，回复显示在下面。\u003c/div>\n        \u003cdiv class=\"field mt14\">\u003clabel for=\"ussd-op\">运营商（USSD_operator，默认取当前运营商名；若发送失败可改成空或运营商代码）\u003c/label>\n          \u003cinput id=\"ussd-op\" class=\"input\" type=\"text\" autocomplete=\"off\" placeholder=\"例如 中国移动\">\n        \u003c/div>\n        \u003cdiv class=\"field\">\u003clabel for=\"ussd-cmd\">USSD 代码\u003c/label>\n          \u003cinput id=\"ussd-cmd\" class=\"input\" type=\"text\" autocomplete=\"off\" placeholder=\"例如 *#888#\">\n        \u003c/div>\n        \u003cdiv class=\"row\">\n          \u003cbutton id=\"ussd-send\" class=\"btn\" type=\"button\">发送\u003c/button>\n          \u003cbutton id=\"ussd-cancel\" class=\"btn ghost\" type=\"button\">取消\u003c/button>\n        \u003c/div>\n        \u003cdiv id=\"ussd-result\" class=\"sub mt14\">—\u003c/div>\n        \u003cdiv class=\"field mt14\" id=\"ussd-reply-wrap\" hidden>\u003clabel for=\"ussd-reply\">回复（运营商要求继续输入时填，例如选 1 查话费余额）\u003c/label>\n          \u003cinput id=\"ussd-reply\" class=\"input\" type=\"text\" autocomplete=\"off\">\n        \u003c/div>\n        \u003cdiv class=\"row\" id=\"ussd-reply-row\" hidden>\u003cbutton id=\"ussd-reply-btn\" class=\"btn\" type=\"button\">回复\u003c/button>\u003c/div>\n        \u003cdiv class=\"sub mt8\">接口依据：实机 service.js（USSD_PROCESS + ussd_write_flag 轮询）。运营商参数取值未在文件中出现，默认用当前运营商名，真机上若失败可改空再试。\u003c/div>\n      \u003c/div>\n\n      \u003cdiv class=\"card\">\n        \u003ch2>固件更新状态\u003c/h2>\n        \u003cdiv class=\"grid\">\n          \u003cdiv class=\"stat\">\u003cdiv class=\"k\">新版本状态\u003c/div>\u003cdiv class=\"v small\" id=\"fw-new\">—\u003c/div>\u003c/div>\n          \u003cdiv class=\"stat\">\u003cdiv class=\"k\">当前升级状态\u003c/div>\u003cdiv class=\"v small\" id=\"fw-cur\">—\u003c/div>\u003c/div>\n          \u003cdiv class=\"stat\">\u003cdiv class=\"k\">上次升级结果\u003c/div>\u003cdiv class=\"v small\" id=\"fw-result\">—\u003c/div>\u003c/div>\n        \u003c/div>\n        \u003cdiv class=\"sub mt14\">只显示状态：执行固件升级没有可靠的 goform 接口（升级要走单独的上传通道，误操作可能变砖），请在官方后台做。\u003c/div>\n      \u003c/div>\n            \u003cdiv class=\"card\">\n              \u003ch2>QCI（QoS 等级）\u003c/h2>\n              \u003cdiv class=\"sub\">QCI 是核心网给数据承载分配的服务质量等级，决定这条承载的优先级、时延和丢包率。数字越小通常优先级越高（例如 QCI 1 是语音，QCI 8/9 是普通上网）。5G 叫 5QI，意思一样。\u003c/div>\n              \u003cdiv class=\"qci-note\" id=\"qci-result\">\n                \u003cb>设备未返回 QCI。\u003c/b>\u003cbr>\n                已查过的字段：\u003ccode>qci\u003c/code>、\u003ccode>QCI\u003c/code>、\u003ccode>qos\u003c/code>、\u003ccode>qos_info\u003c/code>、\u003ccode>5qi\u003c/code>、\u003ccode>5QI\u003c/code>，路由器 Web 接口均未返回有效值。QCI / 5QI 不是 SIM 卡本身的属性，是核心网给承载或 QoS Flow 下发的值，HTTP 接口拿不到；要验证需要 Modem AT / 诊断通道（LTE 可试标准命令 \u003ccode>AT+CGEQOSRDP\u003c/code>，5G SA 通常需要厂商专用命令），本控制台只有 HTTP 接口，没有 AT 透传。\n              \u003c/div>\n              \u003cdiv class=\"grid\">\n                \u003cdiv class=\"stat\">\u003cdiv class=\"k\">当前网络制式\u003c/div>\u003cdiv class=\"v\" id=\"qci-net\">—\u003c/div>\u003c/div>\n                \u003cdiv class=\"stat\">\u003cdiv class=\"k\">活动频段\u003c/div>\u003cdiv class=\"v\" id=\"qci-band\">—\u003c/div>\u003c/div>\n                \u003cdiv class=\"stat\">\u003cdiv class=\"k\">APN 模式\u003c/div>\u003cdiv class=\"v\" id=\"qci-apn\">—\u003c/div>\u003c/div>\n                \u003cdiv class=\"stat\">\u003cdiv class=\"k\">运营商\u003c/div>\u003cdiv class=\"v\" id=\"qci-op\">—\u003c/div>\u003c/div>\n              \u003c/div>\n              \u003cdiv class=\"sub mt14\">上面是接口实际返回的相关字段（制式、频段、运营商），供参考；QCI 本身没有就不编一个给你。\u003c/div>\n            \u003c/div>\n    \u003c/section>\n\n    \u003c!-- Wi-Fi -->\n    \u003csection class=\"page\" id=\"page-wifi\">\n      \u003cdiv class=\"page-head\">\u003ch1>Wi-Fi\u003c/h1>\u003cp>接入点、双频合一、休眠与 WPS 配对。\u003c/p>\u003c/div>\n      \u003cdiv class=\"card\">\n        \u003cdiv class=\"row\">\n          \u003cdiv>\u003ch2>Wi-Fi 接入点\u003c/h2>\u003cdiv class=\"sub\">2.4G / 5G 主网络和访客网络，来自路由器实际返回的数据。\u003c/div>\u003c/div>\n          \u003cdiv class=\"spacer\">\u003c/div>\n          \u003cbutton id=\"wifi-refresh\" class=\"btn ghost small\" type=\"button\">刷新\u003c/button>\n        \u003c/div>\n        \u003cdiv id=\"wifi-list\" class=\"list\">\u003c/div>\n        \u003cdiv id=\"wifi-empty\" class=\"empty\" hidden>未返回 Wi-Fi 接入点信息。\u003c/div>\n      \u003c/div>\n      \u003cdiv class=\"card\">\n        \u003ch2>双频合一\u003c/h2>\n        \u003cdiv class=\"sub\">当前：\u003cb id=\"lbd-cur\">—\u003c/b>\u003c/div>\n        \u003cdiv class=\"field mt14\">\u003clabel class=\"switch-wrap\">\u003cinput id=\"lbd-on\" class=\"switch\" type=\"checkbox\"> \u003cspan>双频合一（2.4G 和 5G 用同一个 Wi-Fi 名称，设备自动选信号好的频段）\u003c/span>\u003c/label>\u003c/div>\n        \u003cdiv class=\"row\">\u003cbutton id=\"lbd-save\" class=\"btn\" type=\"button\">保存双频合一\u003c/button>\u003c/div>\n        \u003cdiv class=\"sub mt8\">开启后 2.4G 和 5G 共用一个 Wi-Fi 名称，设备自动选频段；关闭后 2.4G 和 5G 分开，5G 名称一般是主名称后面加 _5G。切换后 Wi-Fi 会重启，所有无线设备会断开一次，需要重新连接。\u003c/div>\n        \u003cdiv class=\"sub mt8\">接口依据：实机 service.js（switchWiFiModule：SwitchOption=1 时带 wifi_lbd_enable=1 开启合一，SwitchOption=0 分开；SwitchOption 的取值含义是按原厂函数结构推断的，真机上以实际为准）。\u003c/div>\n      \u003c/div>\n      \u003cdiv class=\"card\">\n        \u003ch2>修改 Wi-Fi\u003c/h2>\n        \u003cdiv class=\"field\">\u003clabel for=\"wifi-ap\">选择要改的网络\u003c/label>\n          \u003cselect id=\"wifi-ap\" class=\"input\">\u003c/select>\n        \u003c/div>\n        \u003cdiv class=\"field\">\u003clabel for=\"wifi-ssid\">Wi-Fi 名称（SSID）\u003c/label>\n          \u003cinput id=\"wifi-ssid\" class=\"input\" type=\"text\" autocomplete=\"off\" maxlength=\"32\">\n          \u003cdiv class=\"hint\">中文名可能保存失败，官方说明里 Wi-Fi 名不支持中文。\u003c/div>\n        \u003c/div>\n        \u003cdiv class=\"field\">\u003clabel for=\"wifi-auth\">加密方式\u003c/label>\n          \u003cselect id=\"wifi-auth\" class=\"input\">\n            \u003coption value=\"OPEN\">不加密（OPEN）\u003c/option>\n            \u003coption value=\"WPA2PSK\">WPA2(AES)-PSK\u003c/option>\n            \u003coption value=\"WPA3PSK\">WPA3-PSK\u003c/option>\n            \u003coption value=\"WPA2PSKWPA3PSK\">WPA2-PSK / WPA3-PSK（混合）\u003c/option>\n          \u003c/select>\n        \u003c/div>\n        \u003cdiv class=\"field\" id=\"wifi-pass-wrap\">\u003clabel for=\"wifi-pass\">Wi-Fi 密码（不少于 8 位）\u003c/label>\n          \u003cinput id=\"wifi-pass\" class=\"input\" type=\"password\" autocomplete=\"new-password\" placeholder=\"每次保存都要重新输入密码\">\n          \u003cdiv class=\"hint\">出于安全，当前密码不回显、不预填；改名或改其他设置时也要重新输一次密码才能保存。\u003c/div>\n        \u003c/div>\n        \u003cdiv class=\"field\">\u003clabel for=\"wifi-max\">最大连接数\u003c/label>\n          \u003cinput id=\"wifi-max\" class=\"input\" type=\"number\" min=\"1\" max=\"64\" step=\"1\" inputmode=\"numeric\">\n        \u003c/div>\n        \u003cdiv class=\"field\">\u003clabel class=\"switch-wrap\">\u003cinput id=\"wifi-hide\" class=\"switch\" type=\"checkbox\"> \u003cspan>隐藏 SSID（别人搜不到，手动输入名称才能连）\u003c/span>\u003c/label>\u003c/div>\n        \u003cdiv class=\"field\">\u003clabel class=\"switch-wrap\">\u003cinput id=\"wifi-isolate\" class=\"switch\" type=\"checkbox\"> \u003cspan>客户端隔离（连上 Wi-Fi 的设备之间互相看不到）\u003c/span>\u003c/label>\u003c/div>\n        \u003cdiv class=\"row\">\n          \u003cbutton id=\"wifi-save\" class=\"btn\" type=\"button\">保存 Wi-Fi 设置\u003c/button>\n        \u003c/div>\n        \u003cdiv class=\"sub mt8\">保存后 Wi-Fi 会重启，所有无线设备会断开一次，需要用新名称 / 新密码重新连接。\u003c/div>\n      \u003c/div>\n      \u003cdiv class=\"card\">\n        \u003ch2>Wi-Fi 休眠\u003c/h2>\n        \u003cdiv class=\"field\">\u003clabel for=\"wifi-sleep\">无设备连接多久后休眠 Wi-Fi（0 = 从不）\u003c/label>\n          \u003cselect id=\"wifi-sleep\" class=\"input\">\n            \u003coption value=\"0\">从不休眠\u003c/option>\n            \u003coption value=\"15\">15 分钟\u003c/option>\n            \u003coption value=\"30\">30 分钟\u003c/option>\n            \u003coption value=\"60\">60 分钟\u003c/option>\n            \u003coption value=\"120\">120 分钟\u003c/option>\n          \u003c/select>\n        \u003c/div>\n        \u003cbutton id=\"wifi-sleep-save\" class=\"btn\" type=\"button\">保存休眠设置\u003c/button>\n      \u003c/div>\n      \u003cdiv class=\"card\">\n        \u003ch2>WPS 一键配对\u003c/h2>\n        \u003cdiv class=\"sub\">当前：\u003cb id=\"wps-cur\">—\u003c/b>\u003c/div>\n        \u003cdiv class=\"field mt14\">\u003clabel for=\"wps-band\">配对频段\u003c/label>\n          \u003cselect id=\"wps-band\" class=\"input\">\n            \u003coption value=\"0\">2.4G\u003c/option>\n            \u003coption value=\"1\">5G\u003c/option>\n          \u003c/select>\n        \u003c/div>\n        \u003cdiv class=\"field\">\u003clabel for=\"wps-mode\">配对方式\u003c/label>\n          \u003cselect id=\"wps-mode\" class=\"input\">\n            \u003coption value=\"PBC\">按键配对（PBC：先点开始，再按设备上的 WPS 键）\u003c/option>\n            \u003coption value=\"PIN\">PIN 码配对（在设备上输入下面这台的 PIN，或把设备的 PIN 填进来）\u003c/option>\n          \u003c/select>\n        \u003c/div>\n        \u003cdiv class=\"field\" id=\"wps-pin-wrap\" hidden>\u003clabel for=\"wps-pin\">WPS PIN（8 位）\u003c/label>\n          \u003cinput id=\"wps-pin\" class=\"input\" type=\"text\" inputmode=\"numeric\" autocomplete=\"off\" maxlength=\"8\" placeholder=\"8 位 PIN\">\n        \u003c/div>\n        \u003cdiv class=\"row\">\u003cbutton id=\"wps-start\" class=\"btn\" type=\"button\">开始 WPS 配对\u003c/button>\u003c/div>\n        \u003cdiv class=\"sub mt8\" id=\"wps-status\">状态：—\u003c/div>\n        \u003cdiv class=\"sub mt8\">接口依据：实机 service.js（WIFI_WPS_SET + startWps）。配对有 2 分钟窗口，超时要重新开始。\u003c/div>\n      \u003c/div>\n    \u003c/section>\n\n    \u003c!-- 流量 -->\n    \u003csection class=\"page\" id=\"page-traffic\">\n      \u003cdiv class=\"page-head\">\u003ch1>流量\u003c/h1>\u003cp>本月用量、套餐与校准。\u003c/p>\u003c/div>\n      \u003cdiv class=\"card\">\n        \u003ch2>流量统计\u003c/h2>\n        \u003cdiv class=\"sub\">这里是流量统计，不是签约上下行速率。\u003c/div>\n        \u003cdiv class=\"grid\">\n          \u003cdiv class=\"stat\">\u003cdiv class=\"k\">本月已用（下+上）\u003c/div>\u003cdiv class=\"v\" id=\"tr-month-total\">—\u003c/div>\u003c/div>\n          \u003cdiv class=\"stat\">\u003cdiv class=\"k\">本月下载\u003c/div>\u003cdiv class=\"v\" id=\"tr-month-dl\">—\u003c/div>\u003c/div>\n          \u003cdiv class=\"stat\">\u003cdiv class=\"k\">本月上传\u003c/div>\u003cdiv class=\"v\" id=\"tr-month-ul\">—\u003c/div>\u003c/div>\n          \u003cdiv class=\"stat\">\u003cdiv class=\"k\">本月联网时长\u003c/div>\u003cdiv class=\"v\" id=\"tr-month-time\">—\u003c/div>\u003c/div>\n          \u003cdiv class=\"stat\">\u003cdiv class=\"k\">本次会话下载\u003c/div>\u003cdiv class=\"v\" id=\"tr-sess-dl\">—\u003c/div>\u003c/div>\n          \u003cdiv class=\"stat\">\u003cdiv class=\"k\">本次会话上传\u003c/div>\u003cdiv class=\"v\" id=\"tr-sess-ul\">—\u003c/div>\u003c/div>\n          \u003cdiv class=\"stat\">\u003cdiv class=\"k\">本次会话时长\u003c/div>\u003cdiv class=\"v\" id=\"tr-sess-time\">—\u003c/div>\u003c/div>\n        \u003c/div>\n      \u003c/div>\n\n      \u003cdiv class=\"card\">\n        \u003ch2>套餐\u003c/h2>\n        \u003cdiv class=\"sub\" id=\"tr-plan-summary\">—\u003c/div>\n        \u003cdiv class=\"mt14\">\u003cdiv class=\"bar\">\u003ci id=\"tr-plan-bar\" style=\"width:0%\">\u003c/i>\u003c/div>\u003c/div>\n        \u003cdiv class=\"row mt14\">\n          \u003cbutton id=\"tr-plan-edit\" class=\"btn ghost small\" type=\"button\">修改套餐设置\u003c/button>\n          \u003cbutton id=\"tr-cal-edit\" class=\"btn ghost small\" type=\"button\">手动校准已用流量\u003c/button>\n        \u003c/div>\n        \u003cdiv id=\"tr-plan-form\" class=\"mt14\" hidden>\n          \u003cdiv class=\"field\">\u003clabel for=\"tr-plan-on\">启用套餐限制\u003c/label>\n            \u003clabel class=\"switch-wrap\">\u003cinput id=\"tr-plan-on\" class=\"switch\" type=\"checkbox\"> \u003cspan>开启后按套餐统计提醒\u003c/span>\u003c/label>\n          \u003c/div>\n          \u003cdiv class=\"field\">\u003clabel for=\"tr-plan-size\">套餐大小（GB）\u003c/label>\n            \u003cinput id=\"tr-plan-size\" class=\"input\" type=\"number\" min=\"0\" step=\"0.1\" inputmode=\"decimal\">\n          \u003c/div>\n          \u003cdiv class=\"field\">\u003clabel for=\"tr-plan-alert\">提醒百分比（0–100）\u003c/label>\n            \u003cinput id=\"tr-plan-alert\" class=\"input\" type=\"number\" min=\"0\" max=\"100\" step=\"1\" inputmode=\"numeric\">\n          \u003c/div>\n          \u003cdiv class=\"field\">\u003clabel for=\"tr-plan-autoclear\">每月自动清零\u003c/label>\n            \u003clabel class=\"switch-wrap\">\u003cinput id=\"tr-plan-autoclear\" class=\"switch\" type=\"checkbox\"> \u003cspan>开启\u003c/span>\u003c/label>\n          \u003c/div>\n          \u003cdiv class=\"field\">\u003clabel for=\"tr-plan-date\">每月清零日期（1–31）\u003c/label>\n            \u003cinput id=\"tr-plan-date\" class=\"input\" type=\"number\" min=\"1\" max=\"31\" step=\"1\" inputmode=\"numeric\">\n          \u003c/div>\n          \u003cdiv class=\"row\">\n            \u003cbutton id=\"tr-plan-save\" class=\"btn\" type=\"button\">保存套餐设置\u003c/button>\n            \u003cbutton id=\"tr-plan-cancel\" class=\"btn ghost\" type=\"button\">取消\u003c/button>\n          \u003c/div>\n        \u003c/div>\n        \u003cdiv id=\"tr-cal-form\" class=\"mt14\" hidden>\n          \u003cdiv class=\"field\">\u003clabel for=\"tr-cal-gb\">本月已用流量（GB）\u003c/label>\n            \u003cinput id=\"tr-cal-gb\" class=\"input\" type=\"number\" min=\"0\" step=\"0.01\" inputmode=\"decimal\">\n            \u003cdiv class=\"hint\">把路由器统计的本月已用流量校准成你实际用的数。\u003c/div>\n          \u003c/div>\n          \u003cdiv class=\"row\">\n            \u003cbutton id=\"tr-cal-save\" class=\"btn\" type=\"button\">保存校准\u003c/button>\n            \u003cbutton id=\"tr-cal-cancel\" class=\"btn ghost\" type=\"button\">取消\u003c/button>\n          \u003c/div>\n        \u003c/div>\n      \u003c/div>\n    \u003c/section>\n\n\n    \u003c!-- 短信 -->\n    \u003csection class=\"page\" id=\"page-sms\">\n      \u003cdiv class=\"page-head\">\u003ch1>短信\u003c/h1>\u003cp>收发短信、收件箱与短信中心。\u003c/p>\u003c/div>\n      \u003cdiv class=\"card compose\">\n        \u003ch2>发送短信\u003c/h2>\n        \u003cdiv class=\"field\">\u003clabel for=\"sms-to\">收件人手机号\u003c/label>\n          \u003cinput id=\"sms-to\" class=\"input\" type=\"tel\" placeholder=\"例如 13800000000\" autocomplete=\"off\">\n        \u003c/div>\n        \u003cdiv class=\"field\">\u003clabel for=\"sms-body\">内容（最多 670 字）\u003c/label>\n          \u003ctextarea id=\"sms-body\" class=\"input\" maxlength=\"670\" placeholder=\"输入短信内容…\">\u003c/textarea>\n          \u003cdiv class=\"hint\">\u003cspan id=\"sms-count\">0\u003c/span> / 670 字\u003c/div>\n        \u003c/div>\n        \u003cbutton id=\"sms-send\" class=\"btn\" type=\"button\">发送\u003c/button>\n        \u003cdiv class=\"sub mt8\">发送后会轮询发送状态并提示结果。收件箱在下面，验证码会自动识别、可一键复制。\u003c/div>\n      \u003c/div>\n      \u003cdiv class=\"card\">\n        \u003cdiv class=\"row\">\n          \u003cdiv>\u003ch2>短信收件箱\u003c/h2>\u003cdiv class=\"sub\" id=\"sms-capacity\">—\u003c/div>\u003c/div>\n          \u003cdiv class=\"spacer\">\u003c/div>\n          \u003cbutton id=\"sms-read-all\" class=\"btn ghost small\" type=\"button\" hidden>全部标为已读\u003c/button>\n          \u003cbutton id=\"sms-refresh\" class=\"btn ghost small\" type=\"button\">刷新列表\u003c/button>\n        \u003c/div>\n        \u003cdiv class=\"field mt14\">\u003cinput id=\"sms-filter\" class=\"input small\" type=\"search\" placeholder=\"搜索号码或短信内容…\" autocomplete=\"off\">\u003c/div>\n        \u003cdiv id=\"sms-list\" class=\"list\">\u003c/div>\n        \u003cdiv id=\"sms-empty\" class=\"empty\" hidden>暂无短信。\u003c/div>\n      \u003c/div>\n      \u003cdiv class=\"card\">\n        \u003ch2>短信中心设置\u003c/h2>\n        \u003cdiv class=\"sub\">当前：\u003cb id=\"sms-set-cur\">—\u003c/b>\u003c/div>\n        \u003cdiv class=\"field mt14\">\u003clabel for=\"sms-center\">短信中心号码\u003c/label>\n          \u003cinput id=\"sms-center\" class=\"input\" type=\"tel\" autocomplete=\"off\" placeholder=\"例如 +8613800000000\">\n          \u003cdiv class=\"hint\">一般不用改；发不出短信时先问运营商要正确的中心号码。\u003c/div>\n        \u003c/div>\n        \u003cdiv class=\"field\">\u003clabel for=\"sms-validity\">短信有效期（对方关机时运营商保留多久）\u003c/label>\n          \u003cselect id=\"sms-validity\" class=\"input\">\n            \u003coption value=\"twelve_hours\">12 小时\u003c/option>\n            \u003coption value=\"one_day\">1 天\u003c/option>\n            \u003coption value=\"one_week\">1 周\u003c/option>\n            \u003coption value=\"largest\">最长\u003c/option>\n          \u003c/select>\n        \u003c/div>\n        \u003cdiv class=\"field\">\u003clabel class=\"switch-wrap\">\u003cinput id=\"sms-report\" class=\"switch\" type=\"checkbox\"> \u003cspan>送达报告（对方收到后回一条状态短信）\u003c/span>\u003c/label>\u003c/div>\n        \u003cdiv class=\"row\">\u003cbutton id=\"sms-set-save\" class=\"btn\" type=\"button\">保存短信设置\u003c/button>\u003c/div>\n        \u003cdiv class=\"sub mt8\">接口依据：实机 service.js（SET_MESSAGE_CENTER）。存储位置固定为本机（native）。\u003c/div>\n      \u003c/div>\n    \u003c/section>\n\n    \u003c!-- 连接设备 -->\n    \u003csection class=\"page\" id=\"page-devices\">\n      \u003cdiv class=\"page-head\">\u003ch1>连接设备\u003c/h1>\u003cp>无线与有线设备，改名与拉黑。\u003c/p>\u003c/div>\n      \u003cdiv class=\"card\">\n        \u003ch2>连接设备\u003c/h2>\n        \u003cdiv class=\"field mt8\">\u003cinput id=\"dev-filter\" class=\"input small\" type=\"search\" placeholder=\"搜索设备名、IP 或 MAC…\" autocomplete=\"off\">\u003c/div>\n        \u003cdiv class=\"sub\">只显示路由器实际返回的数据。点“改名”可以给设备起个好认的名字；点“拉黑”把它踢出网络（按 MAC 拉黑，换 MAC 才能回来）。\u003c/div>\n      \u003c/div>\n      \u003cdiv class=\"card\">\n        \u003ch2>无线连接设备 \u003cspan class=\"muted\" id=\"dev-wifi-count\">\u003c/span>\u003c/h2>\n        \u003cdiv id=\"dev-wifi\">\u003c/div>\n      \u003c/div>\n      \u003cdiv class=\"card\">\n        \u003ch2>有线连接设备 \u003cspan class=\"muted\" id=\"dev-lan-count\">\u003c/span>\u003c/h2>\n        \u003cdiv id=\"dev-lan\">\u003c/div>\n      \u003c/div>\n      \u003cdiv class=\"sub\">拉黑在“安全”页：黑名单和防火墙状态放一起了。\u003c/div>\n    \u003c/section>\n\n    \u003c!-- 安全：防火墙可操作 + 黑名单 + 白名单 -->\n    \u003csection class=\"page\" id=\"page-security\">\n      \u003cdiv class=\"page-head\">\u003ch1>安全\u003c/h1>\u003cp>防火墙、端口规则与黑白名单。\u003c/p>\u003c/div>\n      \u003cdiv class=\"card\">\n        \u003ch2>防火墙\u003c/h2>\n        \u003cdiv class=\"field\">\u003clabel class=\"switch-wrap\">\u003cinput id=\"fw-enable\" class=\"switch\" type=\"checkbox\"> \u003cspan>开启端口过滤（防火墙总开关）\u003c/span>\u003c/label>\u003c/div>\n        \u003cdiv class=\"sub\">默认策略只显示不改：策略值的对应关系未在原厂文件里出现，保存时把当前值原样带回。\u003c/div>\n        \u003cdiv class=\"row mt8\">\u003cbutton id=\"fw-save\" class=\"btn\" type=\"button\">保存防火墙设置\u003c/button>\u003c/div>\n        \u003cdiv class=\"grid\">\n          \u003cdiv class=\"stat\">\u003cdiv class=\"k\">防火墙总开关\u003c/div>\u003cdiv class=\"v small\" id=\"fw-switch\">—\u003c/div>\u003c/div>\n          \u003cdiv class=\"stat\">\u003cdiv class=\"k\">防火墙禁用\u003c/div>\u003cdiv class=\"v small\" id=\"fw-disable\">—\u003c/div>\u003c/div>\n          \u003cdiv class=\"stat\">\u003cdiv class=\"k\">默认策略\u003c/div>\u003cdiv class=\"v small\" id=\"fw-policy\">—\u003c/div>\u003c/div>\n          \u003cdiv class=\"stat\">\u003cdiv class=\"k\">ACL 模式\u003c/div>\u003cdiv class=\"v small\" id=\"fw-acl\">—\u003c/div>\u003c/div>\n          \u003cdiv class=\"stat\">\u003cdiv class=\"k\">WAN Ping 过滤\u003c/div>\u003cdiv class=\"v small\" id=\"fw-ping\">—\u003c/div>\u003c/div>\n        \u003c/div>\n      \u003c/div>\n      \u003cdiv class=\"card\">\n        \u003ch2>端口规则\u003c/h2>\n        \u003cdiv class=\"sub\" id=\"fw-rules-note\">—\u003c/div>\n        \u003ch3 class=\"mt14\">端口过滤 \u003cspan class=\"muted\" id=\"fw-pf-state\">\u003c/span>\u003c/h3>\n        \u003cdiv id=\"fw-pf-rules\" class=\"list\">\u003c/div>\n        \u003cdiv class=\"mt14\">\n          \u003cdiv class=\"field\">\u003clabel for=\"pf-mac\">新增过滤规则：设备 MAC（可选，留空 = 所有设备）\u003c/label>\n            \u003cinput id=\"pf-mac\" class=\"input\" type=\"text\" autocomplete=\"off\" placeholder=\"例如 AA:BB:CC:DD:EE:FF\">\n          \u003c/div>\n          \u003cdiv class=\"field\">\u003clabel for=\"pf-sip\">源 IP（可选，留空 = 任意）\u003c/label>\n            \u003cinput id=\"pf-sip\" class=\"input\" type=\"text\" autocomplete=\"off\" placeholder=\"例如 192.168.0.100\">\n          \u003c/div>\n          \u003cdiv class=\"field\">\u003clabel for=\"pf-dip\">目标 IP（可选，留空 = 任意）\u003c/label>\n            \u003cinput id=\"pf-dip\" class=\"input\" type=\"text\" autocomplete=\"off\" placeholder=\"例如 8.8.8.8\">\n          \u003c/div>\n          \u003cdiv class=\"field\">\u003clabel for=\"pf-sport\">源端口（起–止，留空 = 任意）\u003c/label>\n            \u003cdiv class=\"row\">\u003cinput id=\"pf-sport\" class=\"input\" type=\"number\" min=\"1\" max=\"65535\" inputmode=\"numeric\" placeholder=\"起\"> \u003cinput id=\"pf-sport2\" class=\"input\" type=\"number\" min=\"1\" max=\"65535\" inputmode=\"numeric\" placeholder=\"止\">\u003c/div>\n          \u003c/div>\n          \u003cdiv class=\"field\">\u003clabel for=\"pf-dport\">目标端口（起–止，留空 = 任意）\u003c/label>\n            \u003cdiv class=\"row\">\u003cinput id=\"pf-dport\" class=\"input\" type=\"number\" min=\"1\" max=\"65535\" inputmode=\"numeric\" placeholder=\"起\"> \u003cinput id=\"pf-dport2\" class=\"input\" type=\"number\" min=\"1\" max=\"65535\" inputmode=\"numeric\" placeholder=\"止\">\u003c/div>\n          \u003c/div>\n          \u003cdiv class=\"field\">\u003clabel for=\"pf-action\">动作\u003c/label>\n            \u003cselect id=\"pf-action\" class=\"input\">\u003coption value=\"accept\">允许\u003c/option>\u003coption value=\"drop\">禁止\u003c/option>\u003c/select>\n          \u003c/div>\n          \u003cdiv class=\"field\">\u003clabel for=\"pf-proto\">协议\u003c/label>\n            \u003cselect id=\"pf-proto\" class=\"input\">\u003coption value=\"TCP\">TCP\u003c/option>\u003coption value=\"UDP\">UDP\u003c/option>\u003coption value=\"ALL\">全部\u003c/option>\u003c/select>\n          \u003c/div>\n          \u003cdiv class=\"field\">\u003clabel for=\"pf-comment\">备注\u003c/label>\n            \u003cinput id=\"pf-comment\" class=\"input\" type=\"text\" autocomplete=\"off\" maxlength=\"32\">\n          \u003c/div>\n          \u003cdiv class=\"row\">\u003cbutton id=\"pf-add\" class=\"btn\" type=\"button\">新增过滤规则\u003c/button>\u003c/div>\n        \u003c/div>\n        \u003ch3 class=\"mt14\">端口转发 \u003cspan class=\"muted\" id=\"fw-fwd-state\">\u003c/span>\u003c/h3>\n        \u003cdiv class=\"field\">\u003clabel class=\"switch-wrap\">\u003cinput id=\"fw-fwd-enable\" class=\"switch\" type=\"checkbox\"> \u003cspan>开启端口转发\u003c/span>\u003c/label>\u003c/div>\n        \u003cdiv class=\"row\">\u003cbutton id=\"fw-fwd-save\" class=\"btn small\" type=\"button\">保存转发开关\u003c/button>\u003c/div>\n        \u003cdiv id=\"fw-fwd-rules\" class=\"list\">\u003c/div>\n        \u003cdiv class=\"mt14\">\n          \u003cdiv class=\"field\">\u003clabel for=\"fwd-ip\">新增转发规则：内网设备 IP\u003c/label>\n            \u003cinput id=\"fwd-ip\" class=\"input\" type=\"text\" autocomplete=\"off\" placeholder=\"例如 192.168.0.100\">\n          \u003c/div>\n          \u003cdiv class=\"field\">\u003clabel for=\"fwd-port\">外部端口（起–止）\u003c/label>\n            \u003cdiv class=\"row\">\u003cinput id=\"fwd-port\" class=\"input\" type=\"number\" min=\"1\" max=\"65535\" inputmode=\"numeric\" placeholder=\"起\"> \u003cinput id=\"fwd-port2\" class=\"input\" type=\"number\" min=\"1\" max=\"65535\" inputmode=\"numeric\" placeholder=\"止\">\u003c/div>\n          \u003c/div>\n          \u003cdiv class=\"field\">\u003clabel for=\"fwd-proto\">协议\u003c/label>\n            \u003cselect id=\"fwd-proto\" class=\"input\">\u003coption value=\"TCP\">TCP\u003c/option>\u003coption value=\"UDP\">UDP\u003c/option>\u003coption value=\"ALL\">全部\u003c/option>\u003c/select>\n          \u003c/div>\n          \u003cdiv class=\"field\">\u003clabel for=\"fwd-comment\">备注\u003c/label>\n            \u003cinput id=\"fwd-comment\" class=\"input\" type=\"text\" autocomplete=\"off\" maxlength=\"32\">\n          \u003c/div>\n          \u003cdiv class=\"row\">\u003cbutton id=\"fwd-add\" class=\"btn\" type=\"button\">新增转发规则\u003c/button>\u003c/div>\n        \u003c/div>\n        \u003ch3 class=\"mt14\">端口映射 \u003cspan class=\"muted\" id=\"fw-map-state\">\u003c/span>\u003c/h3>\n        \u003cdiv id=\"fw-map-rules\" class=\"list\">\u003c/div>\n        \u003cdiv class=\"mt14\">\n          \u003cdiv class=\"field\">\u003clabel for=\"map-sport\">新增映射规则：源端口（外网访问的端口）\u003c/label>\n            \u003cinput id=\"map-sport\" class=\"input\" type=\"number\" min=\"1\" max=\"65535\" inputmode=\"numeric\" placeholder=\"例如 8080\">\n          \u003c/div>\n          \u003cdiv class=\"field\">\u003clabel for=\"map-dip\">目标 IP（内网设备）\u003c/label>\n            \u003cinput id=\"map-dip\" class=\"input\" type=\"text\" autocomplete=\"off\" placeholder=\"例如 192.168.0.100\">\n          \u003c/div>\n          \u003cdiv class=\"field\">\u003clabel for=\"map-dport\">目标端口（内网设备的端口）\u003c/label>\n            \u003cinput id=\"map-dport\" class=\"input\" type=\"number\" min=\"1\" max=\"65535\" inputmode=\"numeric\" placeholder=\"例如 80\">\n          \u003c/div>\n          \u003cdiv class=\"field\">\u003clabel for=\"map-proto\">协议\u003c/label>\n            \u003cselect id=\"map-proto\" class=\"input\">\u003coption value=\"TCP\">TCP\u003c/option>\u003coption value=\"UDP\">UDP\u003c/option>\u003coption value=\"ALL\">全部\u003c/option>\u003c/select>\n          \u003c/div>\n          \u003cdiv class=\"field\">\u003clabel for=\"map-comment\">备注\u003c/label>\n            \u003cinput id=\"map-comment\" class=\"input\" type=\"text\" autocomplete=\"off\" maxlength=\"32\">\n          \u003c/div>\n          \u003cdiv class=\"row\">\u003cbutton id=\"map-add\" class=\"btn\" type=\"button\">新增映射规则\u003c/button>\u003c/div>\n          \u003cdiv class=\"sub mt8\">新增映射规则的同时会开启端口映射；删光规则后映射开关仍开着（没有规则就不生效）。\u003c/div>\n        \u003c/div>\n        \u003cdiv class=\"sub mt8\">规则照路由器返回的原文显示，没有解析成表格——规则串的内部格式在公开资料里没有说明，解析错了会误导人。删除按槽位号删。\u003c/div>\n      \u003c/div>\n      \u003cdiv class=\"card\">\n        \u003ch2>UPnP · DMZ · SIP ALG · 远程管理\u003c/h2>\n        \u003cdiv class=\"field\">\u003clabel class=\"switch-wrap\">\u003cinput id=\"upnp-on\" class=\"switch\" type=\"checkbox\"> \u003cspan>UPnP（让游戏、下载软件自动开端口）\u003c/span>\u003c/label>\u003c/div>\n        \u003cdiv class=\"row\">\u003cbutton id=\"upnp-save\" class=\"btn small\" type=\"button\">保存 UPnP\u003c/button>\u003c/div>\n        \u003cdiv class=\"field mt14\">\u003clabel class=\"switch-wrap\">\u003cinput id=\"dmz-on\" class=\"switch\" type=\"checkbox\"> \u003cspan>DMZ（把一台内网设备完全暴露到外网，风险高，谨慎开）\u003c/span>\u003c/label>\u003c/div>\n        \u003cdiv class=\"field\">\u003clabel for=\"dmz-ip\">DMZ 主机 IP\u003c/label>\n          \u003cinput id=\"dmz-ip\" class=\"input\" type=\"text\" autocomplete=\"off\" placeholder=\"例如 192.168.0.100\">\n        \u003c/div>\n        \u003cdiv class=\"row\">\u003cbutton id=\"dmz-save\" class=\"btn small\" type=\"button\">保存 DMZ\u003c/button>\u003c/div>\n        \u003cdiv class=\"field mt14\">\u003clabel class=\"switch-wrap\">\u003cinput id=\"sip-on\" class=\"switch\" type=\"checkbox\"> \u003cspan>SIP ALG（语音通话穿透，通话有问题时可关掉试试）\u003c/span>\u003c/label>\u003c/div>\n        \u003cdiv class=\"row\">\u003cbutton id=\"sip-save\" class=\"btn small\" type=\"button\">保存 SIP ALG\u003c/button>\u003c/div>\n        \u003cdiv class=\"field mt14\">\u003clabel class=\"switch-wrap\">\u003cinput id=\"remote-on\" class=\"switch\" type=\"checkbox\"> \u003cspan>远程管理（允许从外网打开路由器后台，风险高，谨慎开）\u003c/span>\u003c/label>\u003c/div>\n        \u003cdiv class=\"field\">\u003clabel class=\"switch-wrap\">\u003cinput id=\"ping-on\" class=\"switch\" type=\"checkbox\"> \u003cspan>WAN Ping 过滤（开启后外网 ping 不通你，隐身）\u003c/span>\u003c/label>\u003c/div>\n        \u003cdiv class=\"row\">\u003cbutton id=\"fw-sys-save\" class=\"btn small\" type=\"button\">保存远程管理 / Ping 过滤\u003c/button>\u003c/div>\n        \u003cdiv class=\"grid mt14\">\n          \u003cdiv class=\"stat\">\u003cdiv class=\"k\">UPnP\u003c/div>\u003cdiv class=\"v small\" id=\"fw-upnp\">—\u003c/div>\u003c/div>\n          \u003cdiv class=\"stat\">\u003cdiv class=\"k\">DMZ\u003c/div>\u003cdiv class=\"v small\" id=\"fw-dmz\">—\u003c/div>\u003c/div>\n          \u003cdiv class=\"stat\">\u003cdiv class=\"k\">DMZ 地址\u003c/div>\u003cdiv class=\"v small\" id=\"fw-dmzip\">—\u003c/div>\u003c/div>\n          \u003cdiv class=\"stat\">\u003cdiv class=\"k\">SIP ALG\u003c/div>\u003cdiv class=\"v small\" id=\"fw-sip\">—\u003c/div>\u003c/div>\n        \u003c/div>\n        \u003cdiv class=\"sub mt8\">接口依据：实机 service.js（UPNP_SETTING / DMZ_SETTING / ALG_SETTING / FW_SYS）。\u003c/div>\n      \u003c/div>\n      \u003cdiv class=\"card\">\n        \u003ch2>域名过滤\u003c/h2>\n        \u003cdiv class=\"sub\" id=\"fw-url-note\">当前规则：\u003cb id=\"fw-url\">—\u003c/b>\u003c/div>\n        \u003cdiv class=\"sub mt8\">只显示：增删域名过滤规则的 goformId 在按需加载的原厂页面模块（firewall/url_filter.js）里，本次保存的实机文件里没有，控制台做不了；要改请在官方后台操作。补全办法见高级页底部的说明。\u003c/div>\n      \u003c/div>\n      \u003cdiv class=\"card\">\n        \u003ch2>上网白名单\u003c/h2>\n        \u003cdiv class=\"sub\">只允许访问白名单里的网址（家长控制用）。\u003c/div>\n        \u003cdiv id=\"site-white-list\" class=\"list\">\u003c/div>\n        \u003cdiv class=\"field mt14\">\u003clabel for=\"site-white-name\">新增：名称\u003c/label>\n          \u003cinput id=\"site-white-name\" class=\"input\" type=\"text\" autocomplete=\"off\" placeholder=\"例如 学习网站\">\n        \u003c/div>\n        \u003cdiv class=\"field\">\u003clabel for=\"site-white-site\">新增：网址\u003c/label>\n          \u003cinput id=\"site-white-site\" class=\"input\" type=\"text\" autocomplete=\"off\" placeholder=\"例如 www.example.com\">\n        \u003c/div>\n        \u003cdiv class=\"row\">\u003cbutton id=\"site-white-add\" class=\"btn\" type=\"button\">新增白名单网址\u003c/button>\u003c/div>\n        \u003cdiv class=\"sub mt8\">接口依据：实机 service.js（ADD_WHITE_SITE / REMOVE_WHITE_SITE）。\u003c/div>\n      \u003c/div>\n      \u003cdiv class=\"card\">\n        \u003ch2>黑名单 \u003cspan class=\"muted\" id=\"dev-black-count\">\u003c/span>\u003c/h2>\n        \u003cdiv class=\"sub\" id=\"dev-black-mode\">—\u003c/div>\n        \u003cdiv id=\"dev-black\">\u003c/div>\n      \u003c/div>\n    \u003c/section>\n\n\n    \u003c!-- 高级：DDNS / SNTP / VPN 状态 / 升级状态 / 重启规则 / 诊断（只读） -->\n    \u003csection class=\"page\" id=\"page-advanced\">\n      \u003cdiv class=\"page-head\">\u003ch1>高级\u003c/h1>\u003cp>VPN、升级、省电、诊断与网络切片。\u003c/p>\u003c/div>\n      \u003cdiv class=\"card\">\n        \u003ch2>DDNS 与远程管理\u003c/h2>\n        \u003cdiv class=\"sub\">DDNS 只显示状态：改 DDNS 的 goformId 在按需加载的原厂页面模块（adm/ddns_settings.js）里，本次保存的实机文件里没有，控制台做不了；远程管理的开关在安全页（UPnP · DMZ · SIP ALG · 远程管理）。\u003c/div>\n        \u003cdiv class=\"grid\">\n          \u003cdiv class=\"stat\">\u003cdiv class=\"k\">DDNS\u003c/div>\u003cdiv class=\"v small\" id=\"adv-ddns\">—\u003c/div>\u003c/div>\n          \u003cdiv class=\"stat\">\u003cdiv class=\"k\">DDNS 模式\u003c/div>\u003cdiv class=\"v small\" id=\"adv-ddns-mode\">—\u003c/div>\u003c/div>\n          \u003cdiv class=\"stat\">\u003cdiv class=\"k\">远程管理\u003c/div>\u003cdiv class=\"v small\" id=\"adv-remote\">—\u003c/div>\u003c/div>\n        \u003c/div>\n      \u003c/div>\n      \u003cdiv class=\"card\">\n        \u003ch2>时间同步（SNTP）\u003c/h2>\n        \u003cdiv class=\"sub\">只显示状态：改服务器的 goformId 在按需加载的原厂页面模块（adm/sntp.js）里，本次保存的实机文件里没有，控制台做不了。\u003c/div>\n        \u003cdiv class=\"grid\">\n          \u003cdiv class=\"stat\">\u003cdiv class=\"k\">服务器 1\u003c/div>\u003cdiv class=\"v small\" id=\"adv-sntp0\">—\u003c/div>\u003c/div>\n          \u003cdiv class=\"stat\">\u003cdiv class=\"k\">服务器 2\u003c/div>\u003cdiv class=\"v small\" id=\"adv-sntp1\">—\u003c/div>\u003c/div>\n          \u003cdiv class=\"stat\">\u003cdiv class=\"k\">服务器 3\u003c/div>\u003cdiv class=\"v small\" id=\"adv-sntp2\">—\u003c/div>\u003c/div>\n          \u003cdiv class=\"stat\">\u003cdiv class=\"k\">夏令时\u003c/div>\u003cdiv class=\"v small\" id=\"adv-sntp-dst\">—\u003c/div>\u003c/div>\n          \u003cdiv class=\"stat\">\u003cdiv class=\"k\">时区\u003c/div>\u003cdiv class=\"v small\" id=\"adv-sntp-tz\">—\u003c/div>\u003c/div>\n          \u003cdiv class=\"stat\">\u003cdiv class=\"k\">对时方式\u003c/div>\u003cdiv class=\"v small\" id=\"adv-sntp-mode\">—\u003c/div>\u003c/div>\n        \u003c/div>\n        \u003cdiv class=\"sub mt8\" id=\"adv-sntp-note\">—\u003c/div>\n      \u003c/div>\n      \u003cdiv class=\"card\">\n        \u003ch2>VPN 客户端\u003c/h2>\n        \u003cdiv class=\"sub\">当前：\u003cb id=\"vpn-cur\">—\u003c/b>\u003c/div>\n        \u003cdiv class=\"grid\">\n          \u003cdiv class=\"stat\">\u003cdiv class=\"k\">L2TP\u003c/div>\u003cdiv class=\"v small\" id=\"adv-l2tp\">—\u003c/div>\u003c/div>\n          \u003cdiv class=\"stat\">\u003cdiv class=\"k\">PPTP\u003c/div>\u003cdiv class=\"v small\" id=\"adv-pptp\">—\u003c/div>\u003c/div>\n          \u003cdiv class=\"stat\">\u003cdiv class=\"k\">IPSec\u003c/div>\u003cdiv class=\"v small\" id=\"adv-ipsec\">—\u003c/div>\u003c/div>\n          \u003cdiv class=\"stat\">\u003cdiv class=\"k\">GRE\u003c/div>\u003cdiv class=\"v small\" id=\"adv-gre\">—\u003c/div>\u003c/div>\n          \u003cdiv class=\"stat\">\u003cdiv class=\"k\">连接状态\u003c/div>\u003cdiv class=\"v small\" id=\"adv-vpn\">—\u003c/div>\u003c/div>\n        \u003c/div>\n        \u003cdiv class=\"field mt14\">\u003clabel for=\"vpn-type\">VPN 类型\u003c/label>\n          \u003cselect id=\"vpn-type\" class=\"input\">\n            \u003coption value=\"PPTP\">PPTP\u003c/option>\n            \u003coption value=\"L2TP\">L2TP\u003c/option>\n            \u003coption value=\"IPSEC\">IPSec\u003c/option>\n          \u003c/select>\n          \u003cdiv class=\"hint\">只做 PPTP / L2TP / IPSec 三种常用类型；GRE / L2TPV3 的接口在实机文件里有，但字段多且冷门，暂不做表单。\u003c/div>\n        \u003c/div>\n        \u003cdiv class=\"field\">\u003clabel for=\"vpn-server\">服务器地址\u003c/label>\n          \u003cinput id=\"vpn-server\" class=\"input\" type=\"text\" autocomplete=\"off\" placeholder=\"例如 vpn.example.com 或 IP\">\n        \u003c/div>\n        \u003cdiv class=\"field\" id=\"vpn-account-wrap\">\u003clabel for=\"vpn-account\">账号\u003c/label>\n          \u003cinput id=\"vpn-account\" class=\"input\" type=\"text\" autocomplete=\"off\">\n        \u003c/div>\n        \u003cdiv class=\"field\" id=\"vpn-pass-wrap\">\u003clabel for=\"vpn-pass\">密码\u003c/label>\n          \u003cinput id=\"vpn-pass\" class=\"input\" type=\"password\" autocomplete=\"off\">\n        \u003c/div>\n        \u003cdiv class=\"field\" id=\"vpn-l2tp-pass-wrap\" hidden>\u003clabel for=\"vpn-l2tp-pass\">L2TP 密钥（预共享密钥）\u003c/label>\n          \u003cinput id=\"vpn-l2tp-pass\" class=\"input\" type=\"password\" autocomplete=\"off\">\n        \u003c/div>\n        \u003cdiv class=\"field\" id=\"vpn-ipsec-wrap\" hidden>\u003clabel class=\"switch-wrap\">\u003cinput id=\"vpn-ipsec-on\" class=\"switch\" type=\"checkbox\"> \u003cspan>L2TP 上启用 IPSec 加密\u003c/span>\u003c/label>\u003c/div>\n        \u003cdiv class=\"field\" id=\"vpn-ipsec-pass-wrap\" hidden>\u003clabel for=\"vpn-ipsec-pass\">IPSec 密码\u003c/label>\n          \u003cinput id=\"vpn-ipsec-pass\" class=\"input\" type=\"password\" autocomplete=\"off\">\n        \u003c/div>\n        \u003cdiv class=\"field\">\u003clabel class=\"switch-wrap\">\u003cinput id=\"vpn-auto\" class=\"switch\" type=\"checkbox\"> \u003cspan>开机自动连接 VPN\u003c/span>\u003c/label>\u003c/div>\n        \u003cdiv class=\"row\">\n          \u003cbutton id=\"vpn-save\" class=\"btn\" type=\"button\">保存 VPN 配置\u003c/button>\n          \u003cbutton id=\"vpn-connect\" class=\"btn ghost\" type=\"button\">连接\u003c/button>\n          \u003cbutton id=\"vpn-disconnect\" class=\"btn ghost\" type=\"button\">断开\u003c/button>\n        \u003c/div>\n        \u003cdiv class=\"sub mt8\">接口依据：实机 service.js（VPN_CLIENT_SET / VPN_CONNECT / VPN_DISCONNECT）。提醒：原厂 L2TP/PPTP 客户端本身据报有问题（官方让等修复），连不上不一定是控制台的问题。\u003c/div>\n      \u003c/div>\n      \u003cdiv class=\"card\">\n        \u003ch2>固件升级\u003c/h2>\n        \u003cdiv class=\"grid\">\n          \u003cdiv class=\"stat\">\u003cdiv class=\"k\">发现新版本\u003c/div>\u003cdiv class=\"v small\" id=\"adv-upg-new\">—\u003c/div>\u003c/div>\n          \u003cdiv class=\"stat\">\u003cdiv class=\"k\">当前升级状态\u003c/div>\u003cdiv class=\"v small\" id=\"adv-upg-cur\">—\u003c/div>\u003c/div>\n          \u003cdiv class=\"stat\">\u003cdiv class=\"k\">上次升级结果\u003c/div>\u003cdiv class=\"v small\" id=\"adv-upg-result\">—\u003c/div>\u003c/div>\n          \u003cdiv class=\"stat\">\u003cdiv class=\"k\">升级包\u003c/div>\u003cdiv class=\"v small\" id=\"adv-upg-pkg\">—\u003c/div>\u003c/div>\n          \u003cdiv class=\"stat\">\u003cdiv class=\"k\">自动升级\u003c/div>\u003cdiv class=\"v small\" id=\"adv-upg-auto\">—\u003c/div>\u003c/div>\n        \u003c/div>\n        \u003cdiv class=\"row mt14\">\n          \u003cbutton id=\"upg-check\" class=\"btn\" type=\"button\">检查更新\u003c/button>\n        \u003c/div>\n        \u003cdiv class=\"field mt14\">\u003clabel for=\"upg-mode\">自动升级方式\u003c/label>\n          \u003cselect id=\"upg-mode\" class=\"input\">\n            \u003coption value=\"0\">不自动升级\u003c/option>\n            \u003coption value=\"1\">有新版本自动下载并安装\u003c/option>\n            \u003coption value=\"2\">只提醒，不自动安装\u003c/option>\n          \u003c/select>\n        \u003c/div>\n        \u003cdiv class=\"field\">\u003clabel for=\"upg-interval\">自动检查间隔（天）\u003c/label>\n          \u003cinput id=\"upg-interval\" class=\"input\" type=\"number\" min=\"1\" max=\"30\" step=\"1\" inputmode=\"numeric\">\n        \u003c/div>\n        \u003cdiv class=\"field\">\u003clabel class=\"switch-wrap\">\u003cinput id=\"upg-roam\" class=\"switch\" type=\"checkbox\"> \u003cspan>漫游时也允许自动升级\u003c/span>\u003c/label>\u003c/div>\n        \u003cdiv class=\"row\">\u003cbutton id=\"upg-save\" class=\"btn\" type=\"button\">保存自动升级设置\u003c/button>\u003c/div>\n        \u003cdiv class=\"sub mt8\">只做检查 + 自动升级设置：执行升级没有 goform 接口（升级走单独的上传通道，误操作可能变砖），请在官方后台做。\u003c/div>\n      \u003c/div>\n      \u003cdiv class=\"card\">\n        \u003ch2>省电与开机\u003c/h2>\n        \u003cdiv class=\"sub\" id=\"adv-reboot\">—\u003c/div>\n        \u003cdiv class=\"field\">\u003clabel class=\"switch-wrap\">\u003cinput id=\"fastboot-on\" class=\"switch\" type=\"checkbox\"> \u003cspan>快速开机（跳过部分自检，开机更快）\u003c/span>\u003c/label>\u003c/div>\n        \u003cdiv class=\"field\">\u003clabel class=\"switch-wrap\">\u003cinput id=\"lowcurrent-on\" class=\"switch\" type=\"checkbox\"> \u003cspan>小电流模式（充电电流小，发热低，充电慢）\u003c/span>\u003c/label>\u003c/div>\n        \u003cdiv class=\"field\">\u003clabel class=\"switch-wrap\">\u003cinput id=\"psrestart-on\" class=\"switch\" type=\"checkbox\"> \u003cspan>无服务自动重启（长时间没信号时自动重启设备）\u003c/span>\u003c/label>\u003c/div>\n        \u003cdiv class=\"field\">\u003clabel class=\"switch-wrap\">\u003cinput id=\"pcie-on\" class=\"switch\" type=\"checkbox\"> \u003cspan>PCIe 省电（Wi-Fi 芯片省电）\u003c/span>\u003c/label>\u003c/div>\n        \u003cdiv class=\"row\">\u003cbutton id=\"power-save\" class=\"btn\" type=\"button\">保存省电设置\u003c/button>\u003c/div>\n        \u003cdiv class=\"sub mt8\">无服务自动重启的当前值读不到（原厂文件里没有对应的读字段），开关显示的是你上次保存的选择，保存即按选择写入。自动省电（SET_AUTO_POWER_SAVE）接口在文件里，但原厂配置里这项是关闭的（AUTO_POWER_SAVE_SUPPORT:false），所以不做。\u003c/div>\n      \u003c/div>\n      \u003cdiv class=\"card\">\n        \u003ch2>网页休眠 · 限时 · 温控 · 夜间 LED\u003c/h2>\n        \u003cdiv class=\"field\">\u003clabel class=\"switch-wrap\">\u003cinput id=\"webwake-on\" class=\"switch\" type=\"checkbox\"> \u003cspan>网页唤醒（定时唤醒后台页面）\u003c/span>\u003c/label>\u003c/div>\n        \u003cdiv class=\"field\">\u003clabel for=\"webwake-time\">唤醒时间\u003c/label>\n          \u003cinput id=\"webwake-time\" class=\"input\" type=\"time\">\n        \u003c/div>\n        \u003cdiv class=\"field\">\u003clabel class=\"switch-wrap\">\u003cinput id=\"websleep-on\" class=\"switch\" type=\"checkbox\"> \u003cspan>网页休眠（定时让后台页面休眠）\u003c/span>\u003c/label>\u003c/div>\n        \u003cdiv class=\"field\">\u003clabel for=\"websleep-time\">休眠时间\u003c/label>\n          \u003cinput id=\"websleep-time\" class=\"input\" type=\"time\">\n        \u003c/div>\n        \u003cdiv class=\"field\">\u003clabel for=\"time-limited\">限时上网（分钟/天，0 = 不限）\u003c/label>\n          \u003cinput id=\"time-limited\" class=\"input\" type=\"number\" min=\"0\" step=\"1\" inputmode=\"numeric\">\n        \u003c/div>\n        \u003cdiv class=\"row\">\u003cbutton id=\"tsw-save\" class=\"btn\" type=\"button\">保存休眠 / 限时\u003c/button>\u003c/div>\n        \u003cdiv class=\"field mt14\">\u003clabel class=\"switch-wrap\">\u003cinput id=\"thermal-on\" class=\"switch\" type=\"checkbox\"> \u003cspan>温控（过热时降速保护）\u003c/span>\u003c/label>\u003c/div>\n        \u003cdiv class=\"field\">\u003clabel class=\"switch-wrap\">\u003cinput id=\"thermal-led-on\" class=\"switch\" type=\"checkbox\"> \u003cspan>温控指示灯（过热时亮灯提醒）\u003c/span>\u003c/label>\u003c/div>\n        \u003cdiv class=\"row\">\u003cbutton id=\"thermal-save\" class=\"btn\" type=\"button\">保存温控\u003c/button>\u003c/div>\n        \u003cdiv class=\"field mt14\">\u003clabel class=\"switch-wrap\">\u003cinput id=\"led-night-on\" class=\"switch\" type=\"checkbox\"> \u003cspan>夜间 LED 熄灭（晚上关掉机身指示灯）\u003c/span>\u003c/label>\u003c/div>\n        \u003cdiv class=\"field\">\u003clabel for=\"led-start\">熄灯开始\u003c/label>\n          \u003cinput id=\"led-start\" class=\"input\" type=\"time\">\n        \u003c/div>\n        \u003cdiv class=\"field\">\u003clabel for=\"led-end\">熄灯结束\u003c/label>\n          \u003cinput id=\"led-end\" class=\"input\" type=\"time\">\n        \u003c/div>\n        \u003cdiv class=\"field\">\u003clabel class=\"switch-wrap\">\u003cinput id=\"led-all-off\" class=\"switch\" type=\"checkbox\"> \u003cspan>熄灯时关掉全部 LED\u003c/span>\u003c/label>\u003c/div>\n        \u003cdiv class=\"row\">\u003cbutton id=\"led-save\" class=\"btn\" type=\"button\">保存夜间 LED\u003c/button>\u003c/div>\n        \u003cdiv class=\"sub mt8\">接口依据：实机 service.js（MGMT_CONTROL_POWER_ON_SPEED / LOW_CURRENT_MODE_SWITCH / PS_NO_SERVICE_RESTART_SET / PCIE_POWERSAVE_SWITCH / SAVE_TSW / SAVE_TIME_LIMITED / SET_THERMAL_CONTROL / SET_DEVICE_LED）。\u003c/div>\n      \u003c/div>\n      \u003cdiv class=\"card\">\n        \u003ch2>IMS 与语音调试\u003c/h2>\n        \u003cdiv class=\"sub\">当前：\u003cb id=\"ims-cur\">—\u003c/b>\u003c/div>\n        \u003cdiv class=\"field mt14\">\u003clabel class=\"switch-wrap\">\u003cinput id=\"ims-on\" class=\"switch\" type=\"checkbox\"> \u003cspan>IMS 调试（VoLTE / 语音业务调试开关）\u003c/span>\u003c/label>\u003c/div>\n        \u003cdiv class=\"field\">\u003clabel class=\"switch-wrap\">\u003cinput id=\"voice-on\" class=\"switch\" type=\"checkbox\"> \u003cspan>语音调试\u003c/span>\u003c/label>\u003c/div>\n        \u003cdiv class=\"row\">\u003cbutton id=\"ims-save\" class=\"btn\" type=\"button\">保存 IMS / 语音调试\u003c/button>\u003c/div>\n        \u003cdiv class=\"sub mt8\">接口依据：实机 service.js（VOICE_DEBUG_IMS_SET / VOICE_DEBUG_VOICE_SET）。这两个是调试开关，平时保持关闭；通话有问题需要抓日志时才开。\u003c/div>\n      \u003c/div>\n      \u003cdiv class=\"card\">\n        \u003ch2>网络切片\u003c/h2>\n        \u003cdiv class=\"sub\">当前：\u003cb id=\"slice-cur\">—\u003c/b>\u003c/div>\n        \u003cdiv class=\"field mt14\">\u003clabel class=\"switch-wrap\">\u003cinput id=\"slice3-on\" class=\"switch\" type=\"checkbox\"> \u003cspan>切片 PDN3\u003c/span>\u003c/label>\u003c/div>\n        \u003cdiv class=\"field\">\u003clabel class=\"switch-wrap\">\u003cinput id=\"slice4-on\" class=\"switch\" type=\"checkbox\"> \u003cspan>切片 PDN4\u003c/span>\u003c/label>\u003c/div>\n        \u003cdiv class=\"row\">\u003cbutton id=\"slice-save\" class=\"btn\" type=\"button\">保存切片开关\u003c/button>\u003c/div>\n        \u003cdiv class=\"sub mt8\">只做 PDN3 / PDN4 的开关：APN 配置（MP_APN_config）等字段读回来原样带回，不提供编辑——它的格式未在原厂文件里出现。接口依据：实机 service.js（PPP_DIAL_MULTI_PDNS_PARAM_SET）。\u003c/div>\n      \u003c/div>\n      \u003cdiv class=\"card\">\n        \u003ch2>TR069 远程管理\u003c/h2>\n        \u003cdiv class=\"sub\">当前：\u003cb id=\"tr069-cur\">—\u003c/b>\u003c/div>\n        \u003cdiv class=\"field mt14\">\u003clabel class=\"switch-wrap\">\u003cinput id=\"tr069-module-on\" class=\"switch\" type=\"checkbox\"> \u003cspan>启用 TR069 模块（运营商远程管理）\u003c/span>\u003c/label>\u003c/div>\n        \u003cdiv class=\"row\">\u003cbutton id=\"tr069-save\" class=\"btn\" type=\"button\">保存 TR069 模块\u003c/button>\u003c/div>\n        \u003cdiv class=\"row mt8\">\u003cbutton id=\"tr069-restore\" class=\"btn ghost\" type=\"button\">恢复 TR069 默认参数\u003c/button>\u003c/div>\n        \u003cdiv class=\"sub mt8\">TR069 完整配置（服务器地址、账号等）的写接口 goformId 在页面模块里，本文件里没有，只做模块开关 + 恢复默认。接口依据：实机 service.js（TR069_MODULE_SET / RESTORE_TR069_DEFAULT_PARA）。\u003c/div>\n      \u003c/div>\n      \u003cdiv class=\"card\">\n        \u003ch2>诊断\u003c/h2>\n        \u003cdiv class=\"sub\">路由器返回的诊断相关字段（多数固件上是空的，空就是没返回，不是 bug）。执行 ping / traceroute 没有可靠的接口。\u003c/div>\n        \u003cdiv class=\"grid\">\n          \u003cdiv class=\"stat\">\u003cdiv class=\"k\">诊断检查\u003c/div>\u003cdiv class=\"v small\" id=\"adv-diag-check\">—\u003c/div>\u003c/div>\n          \u003cdiv class=\"stat\">\u003cdiv class=\"k\">诊断地址\u003c/div>\u003cdiv class=\"v small\" id=\"adv-diag-url\">—\u003c/div>\u003c/div>\n          \u003cdiv class=\"stat\">\u003cdiv class=\"k\">本地域名\u003c/div>\u003cdiv class=\"v small\" id=\"adv-diag-domain\">—\u003c/div>\u003c/div>\n          \u003cdiv class=\"stat\">\u003cdiv class=\"k\">链路检测 ping 次数\u003c/div>\u003cdiv class=\"v small\" id=\"adv-diag-ping\">—\u003c/div>\u003c/div>\n        \u003c/div>\n        \u003cdiv class=\"row mt14\">\u003cbutton id=\"diag-detect\" class=\"btn\" type=\"button\">开始信号质量检测\u003c/button>\u003c/div>\n        \u003cdiv class=\"sub mt8\" id=\"diag-detect-note\">信号质量检测会触发一次 Modem 信号评估，结果体现在信号格和 RSRP/SINR 上（总览页看）。\u003c/div>\n        \u003ch3 class=\"mt14\">温度\u003c/h3>\n        \u003cdiv class=\"grid\" id=\"adv-temps\">\u003c/div>\n      \u003c/div>\n      \u003cdiv class=\"card\">\n        \u003ch2>MTU / MSS\u003c/h2>\n        \u003cdiv class=\"sub\">当前：\u003cb id=\"mtu-cur\">—\u003c/b>\u003c/div>\n        \u003cdiv class=\"field mt14\">\u003clabel for=\"mtu-val\">MTU（最大传输单元，常见 1500；移动网络一般 1400–1500）\u003c/label>\n          \u003cinput id=\"mtu-val\" class=\"input\" type=\"number\" min=\"576\" max=\"1500\" step=\"1\" inputmode=\"numeric\">\n        \u003c/div>\n        \u003cdiv class=\"field\">\u003clabel for=\"mss-val\">TCP MSS（一般比 MTU 小 40）\u003c/label>\n          \u003cinput id=\"mss-val\" class=\"input\" type=\"number\" min=\"536\" max=\"1460\" step=\"1\" inputmode=\"numeric\">\n        \u003c/div>\n        \u003cdiv class=\"row\">\u003cbutton id=\"mtu-save\" class=\"btn\" type=\"button\">保存 MTU / MSS\u003c/button>\u003c/div>\n        \u003cdiv class=\"sub mt8\">改错 MTU 会导致部分网站打不开、速度变慢；不知道就别改，改完若上网异常改回 1500 / 1460。接口依据：实机 service.js（SET_DEVICE_MTU）。\u003c/div>\n      \u003c/div>\n      \u003cdiv class=\"card\">\n        \u003ch2>本控制台暂不支持的功能\u003c/h2>\n        \u003cdiv class=\"sub\">下面这些在原厂后台有，但写接口的 goformId 不在本次保存的实机 service.js 里（在按需加载的页面模块 JS 里，没保存下来），所以控制台不做——不编参数、不猜接口，写坏了可能锁卡或丢配置。要补的话，把对应页面在原厂后台打开后 Ctrl+S 保存，把 `_files` 文件夹里的页面 JS 发来即可（方法见最下面一行）：\u003c/div>\n        \u003cdiv class=\"list\">\n          \u003cdiv class=\"item\">\u003cdiv class=\"t1\">DDNS 改动\u003c/div>\u003cdiv class=\"t2\">写 goformId 在 adm/ddns_settings.js 里，本次没保存下来；只读显示正常。\u003c/div>\u003c/div>\n          \u003cdiv class=\"item\">\u003cdiv class=\"t1\">SNTP（时间同步）改动\u003c/div>\u003cdiv class=\"t2\">写 goformId 在 adm/sntp.js 里，本次没保存下来；只读显示正常。\u003c/div>\u003c/div>\n          \u003cdiv class=\"item\">\u003cdiv class=\"t1\">域名过滤增 / 删\u003c/div>\u003cdiv class=\"t2\">写 goformId 在 firewall/url_filter.js 里，本次没保存下来；只读显示正常。\u003c/div>\u003c/div>\n          \u003cdiv class=\"item\">\u003cdiv class=\"t1\">备份和恢复\u003c/div>\u003cdiv class=\"t2\">service.js 里没有任何备份/恢复的文件接口（全文无 backup）；恢复出厂已在设置页做了。\u003c/div>\u003c/div>\n          \u003cdiv class=\"item\">\u003cdiv class=\"t1\">定时重启的写\u003c/div>\u003cdiv class=\"t2\">写 goformId 在 adm/restart_schedule.js 里；且 v1.3.0 用的 RESTART_SCHEDULE_SETTING 不在本实机 service.js 里（全文 0 次），设置页的定时重启在真机上可能无效——以高级页这里显示的固件重启规则为准。\u003c/div>\u003c/div>\n          \u003cdiv class=\"item\">\u003cdiv class=\"t1\">静态 DHCP（绑定 IP）\u003c/div>\u003cdiv class=\"t2\">增/删的 goformId 在页面模块里；且原厂配置里这项是关闭的（STATION_BIND_SUPPORT:false）。\u003c/div>\u003c/div>\n          \u003cdiv class=\"item\">\u003cdiv class=\"t1\">TR069 完整配置 / 系统日志 / VoIP 账号设置\u003c/div>\u003cdiv class=\"t2\">写的 goformId 都在各自的页面模块里；TR069 模块开关和恢复默认已在上面做了。\u003c/div>\u003c/div>\n          \u003cdiv class=\"item\">\u003cdiv class=\"t1\">Wi-Fi 高级（信道 / 带宽 / 速率）与覆盖范围\u003c/div>\u003cdiv class=\"t2\">接口在（SET_WIFI_INFO / SET_WIFI_COVERAGE），但取值域与双芯片分工在页面模块里，怕改错信道导致没 Wi-Fi。\u003c/div>\u003c/div>\n          \u003cdiv class=\"item\">\u003cdiv class=\"t1\">固件升级执行\u003c/div>\u003cdiv class=\"t2\">只有检查和自动升级设置，没有开始升级的 goformId（升级走单独的上传通道，有变砖风险）。\u003c/div>\u003c/div>\n          \u003cdiv class=\"item\">\u003cdiv class=\"t1\">QCI\u003c/div>\u003cdiv class=\"t2\">Web 接口不返回（网络页里有说明）；需要 Modem AT / 诊断通道，本控制台只有 HTTP 接口。\u003c/div>\u003c/div>\n        \u003c/div>\n        \u003cdiv class=\"sub mt8\">接口清单全文：控制台目录里的 INTERFACE_INVENTORY_v1.6.0.md（每个接口的 goformId、参数、来源都在里面）。\u003c/div>\n      \u003c/div>\n    \u003c/section>\n\n    \u003c!-- 设置 -->\n    \u003csection class=\"page\" id=\"page-settings\">\n      \u003cdiv class=\"page-head\">\u003ch1>设置\u003c/h1>\u003cp>账号与访问、局域网、设备管理与关于。\u003c/p>\u003c/div>\n      \u003cdiv class=\"tag-group\">账号与访问\u003c/div>\n      \u003cdiv class=\"card\">\n        \u003ch2>路由器地址\u003c/h2>\n        \u003cdiv class=\"field\">\u003clabel for=\"set-addr\">路由器地址\u003c/label>\n          \u003cinput id=\"set-addr\" class=\"input\" type=\"text\" autocomplete=\"off\" spellcheck=\"false\">\n          \u003cdiv class=\"hint\">改完点保存，会断开当前会话并重新登录。\u003c/div>\n        \u003c/div>\n        \u003cbutton id=\"set-addr-save\" class=\"btn\" type=\"button\">保存地址\u003c/button>\n      \u003c/div>\n      \u003cdiv class=\"card\">\n        \u003ch2>修改管理员密码\u003c/h2>\n        \u003cdiv class=\"sub\">改的是登录路由器后台的密码（就是登录页输的那个）。改完以后要用新密码登录，旧密码就作废了。\u003c/div>\n        \u003cdiv class=\"field mt14\">\u003clabel for=\"set-pw-old\">当前密码\u003c/label>\n          \u003cinput id=\"set-pw-old\" class=\"input\" type=\"password\" autocomplete=\"current-password\">\n        \u003c/div>\n        \u003cdiv class=\"field\">\u003clabel for=\"set-pw-new\">新密码\u003c/label>\n          \u003cinput id=\"set-pw-new\" class=\"input\" type=\"password\" autocomplete=\"new-password\">\n        \u003c/div>\n        \u003cdiv class=\"field\">\u003clabel for=\"set-pw-confirm\">再输一次新密码\u003c/label>\n          \u003cinput id=\"set-pw-confirm\" class=\"input\" type=\"password\" autocomplete=\"new-password\">\n        \u003c/div>\n        \u003cbutton id=\"set-pw-save\" class=\"btn\" type=\"button\">修改密码\u003c/button>\n      \u003c/div>\n      \u003cdiv class=\"tag-group\">局域网\u003c/div>\n      \u003cdiv class=\"card\">\n        \u003ch2>局域网 / DHCP\u003c/h2>\n        \u003cdiv class=\"sub\">当前：\u003cb id=\"lan-cur\">—\u003c/b>\u003c/div>\n        \u003cdiv class=\"field mt14\">\u003clabel for=\"lan-ip\">网关地址（LAN IP）\u003c/label>\n          \u003cinput id=\"lan-ip\" class=\"input\" type=\"text\" autocomplete=\"off\" spellcheck=\"false\" placeholder=\"例如 192.168.0.1\">\n          \u003cdiv class=\"hint\">改网关地址就是改路由器后台地址，改完要到新地址登录，控制台登录页的地址也要跟着改。\u003c/div>\n        \u003c/div>\n        \u003cdiv class=\"field\">\u003clabel for=\"lan-mask\">子网掩码\u003c/label>\n          \u003cinput id=\"lan-mask\" class=\"input\" type=\"text\" autocomplete=\"off\" spellcheck=\"false\" placeholder=\"例如 255.255.255.0\">\n        \u003c/div>\n        \u003cdiv class=\"field\">\u003clabel for=\"lan-dhcp-type\">DHCP（自动分配 IP）\u003c/label>\n          \u003cselect id=\"lan-dhcp-type\" class=\"input\">\n            \u003coption value=\"SERVER\">开启（路由器自动给设备分配 IP）\u003c/option>\n            \u003coption value=\"DISABLE\">关闭（设备要手动设 IP 才能上网）\u003c/option>\n          \u003c/select>\n        \u003c/div>\n        \u003cdiv class=\"field\">\u003clabel for=\"lan-dhcp-start\">DHCP 起始地址\u003c/label>\n          \u003cinput id=\"lan-dhcp-start\" class=\"input\" type=\"text\" autocomplete=\"off\" spellcheck=\"false\" placeholder=\"例如 192.168.0.2\">\n        \u003c/div>\n        \u003cdiv class=\"field\">\u003clabel for=\"lan-dhcp-end\">DHCP 结束地址\u003c/label>\n          \u003cinput id=\"lan-dhcp-end\" class=\"input\" type=\"text\" autocomplete=\"off\" spellcheck=\"false\" placeholder=\"例如 192.168.0.254\">\n        \u003c/div>\n        \u003cdiv class=\"field\">\u003clabel for=\"lan-dhcp-lease\">DHCP 租期（小时）\u003c/label>\n          \u003cinput id=\"lan-dhcp-lease\" class=\"input\" type=\"number\" min=\"1\" step=\"1\" inputmode=\"numeric\" placeholder=\"例如 24\">\n        \u003c/div>\n        \u003cbutton id=\"lan-save\" class=\"btn\" type=\"button\">保存局域网设置\u003c/button>\n        \u003cdiv class=\"sub mt8\">保存后设备会重启网络，Wi-Fi 会断开一次；改了网关地址的话，要用新地址重新登录。\u003c/div>\n      \u003c/div>\n      \u003cdiv class=\"tag-group\">设备管理\u003c/div>\n      \u003cdiv class=\"card\">\n        \u003ch2>定时重启\u003c/h2>\n        \u003cdiv class=\"sub\">当前：\u003cb id=\"reboot-sched-cur\">—\u003c/b>\u003c/div>\n        \u003cdiv class=\"field mt14\">\u003clabel class=\"switch-wrap\">\u003cinput id=\"reboot-sched-on\" class=\"switch\" type=\"checkbox\"> \u003cspan>每天定时重启一次\u003c/span>\u003c/label>\u003c/div>\n        \u003cdiv class=\"field\">\u003clabel for=\"reboot-sched-time\">重启时间\u003c/label>\n          \u003cinput id=\"reboot-sched-time\" class=\"input\" type=\"time\" value=\"04:00\">\n        \u003c/div>\n        \u003cbutton id=\"reboot-sched-save\" class=\"btn\" type=\"button\">保存定时重启\u003c/button>\n      \u003c/div>\n      \u003cdiv class=\"card\">\n        \u003ch2>Wi-Fi 开关\u003c/h2>\n        \u003cdiv class=\"sub\">当前状态：\u003cb id=\"set-wifi-state\">—\u003c/b>\u003c/div>\n        \u003cdiv class=\"row mt14\">\n          \u003cbutton id=\"set-wifi-on\" class=\"btn\" type=\"button\">开启 Wi-Fi\u003c/button>\n          \u003cbutton id=\"set-wifi-off\" class=\"btn ghost\" type=\"button\">关闭 Wi-Fi\u003c/button>\n        \u003c/div>\n        \u003cdiv class=\"sub mt8\">关闭 Wi-Fi 会立即断开当前连接（包括你正在用的这台设备）。\u003c/div>\n      \u003c/div>\n      \u003cdiv class=\"card\">\n        \u003ch2>设备控制\u003c/h2>\n        \u003cdiv class=\"row\">\n          \u003cbutton id=\"set-reboot\" class=\"btn danger\" type=\"button\">重启设备\u003c/button>\n          \u003cbutton id=\"set-shutdown\" class=\"btn danger\" type=\"button\">关闭设备\u003c/button>\n        \u003c/div>\n        \u003cdiv class=\"sub mt8\">重启 / 关闭是不可逆操作：点一下按钮变红显示“确认”，再点一下才真正执行；5 秒内不点第二下会自动恢复。\u003c/div>\n      \u003c/div>\n      \u003cdiv class=\"card\">\n        \u003ch2>恢复出厂设置\u003c/h2>\n        \u003cdiv class=\"warn\">恢复出厂会清空全部配置：Wi-Fi 名称和密码、APN、流量套餐、短信、黑名单、锁频段/锁小区，全部回到出厂状态。恢复后要用默认地址 http://192.168.0.1 和默认密码重新登录、重新设置。操作前请先记下 Wi-Fi 密码和 APN。\u003c/div>\n        \u003cdiv class=\"row mt14\">\u003cbutton id=\"set-factory-reset\" class=\"btn danger\" type=\"button\">恢复出厂设置\u003c/button>\u003c/div>\n        \u003cdiv class=\"sub mt8\" id=\"factory-reset-note\">接口依据：实机 service.js（RESTORE_FACTORY_SETTINGS + restore_flag 轮询）。执行后设备会重启，控制台会断开连接，等设备重启完成后再用默认地址登录。\u003c/div>\n      \u003c/div>\n      \u003cdiv class=\"tag-group\">关于\u003c/div>\n      \u003cdiv class=\"card\">\n        \u003ch2>关于\u003c/h2>\n        \u003cdiv class=\"sub\">U50 Pro 控制台 v1.7.0 随身版 · 第三方管理后台，直连模式：跑在原厂页面里，直接调路由器 HTTP 接口（\u003ccode>/goform/goform_get_cmd_process\u003c/code> / \u003ccode>/goform/goform_set_cmd_process\u003c/code>），不用电脑、不用代理。VPN / 代理功能设备接口不提供，不在控制台里。数据只存在浏览器本地，不上传任何地方。\u003c/div>\n        \u003cdiv class=\"sub mt8\">随身版：手机连着 U50 的 Wi-Fi 就能用，在家和出门都一样。用法：手机浏览器打开原厂页面 http://192.168.0.1，点收藏夹里的“U50 控制台”即可。PC 版（电脑 Node 服务）功能完全一样，只是换了一种进法。\u003c/div>\n        \u003cdiv class=\"sub mt8\" id=\"about-fw\">固件更新状态：—\u003c/div>\n      \u003c/div>\n    \u003c/section>\n\n  \u003c/main>\n\u003c/div>\n\n\u003cdiv id=\"toast\" class=\"toast\" role=\"status\">\u003cspan class=\"tdot\">\u003c/span>\u003cspan id=\"toast-text\">\u003c/span>\u003c/div>\n\u003cbutton id=\"to-top\" class=\"to-top\" type=\"button\" aria-label=\"回到顶部\" hidden>↑\u003c/button>\n\u003cscript>window.__U50PRO_DIRECT__=true;\u003c/script>\n\u003cscript src=\"https://HOST/u50pro-portable/app.js\">\u003c/script>\n\u003c/body>\n\u003c/html>\n";
